      "lqs": [
        {
                "q": "\u062f \u062f\u06d0 \u0644\u0648\u0633\u062a \u0627\u062e\u0644\u0627\u0642\u064a \u0627\u0648 \u069a\u0648\u0648\u0646\u06cc\u0632 \u067e\u06cc\u063a\u0627\u0645 \u0685\u0647 \u062f\u06cc\u061f",
                "ans": "\u062c\u0648 \u0627\u0633 \u062f\u0646\u06cc\u0627 \u06a9\u0627 \u067e\u06cc\u062f\u0627 \u06a9\u0631\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0627\u0648\u0631 \u0633\u0628 \u06a9\u06d2 \u0644\u06cc\u06d2 \u062c\u0627\u0626\u06d2 \u067e\u0646\u0627\u06c1 \u06c1\u06d2\u060c \u0648\u06c1 \u0627\u0644\u0644\u06c1 \u06c1\u06d2\u06d4 \u062c\u0648 \u0633\u0628 \u06a9\u0627 \u0645\u0633\u06cc\u062d\u0627 \u0627\u0648\u0631 \u0645\u062f\u062f\u06af\u0627\u0631 \u06c1\u06d2\u060c \u06c1\u0631 \u062c\u06af\u06c1 \u0645\u0648\u062c\u0648\u062f \u0644\u06cc\u06a9\u0646 \u0646\u0638\u0631\u0648\u06ba \u0633\u06d2 \u067e\u0648\u0634\u06cc\u062f\u06c1 \u0627\u0648\u0631 \u06cc\u06a9\u062a\u0627 \u06c1\u06d2\u06d4 \u0646\u06c1 \u0627\u0633 \u06a9\u06cc \u06a9\u0648\u0626\u06cc \u0627\u0648\u0644\u0627\u062f \u06c1\u06d2 \u0627\u0648\u0631 \u0646\u06c1 \u0648\u06c1 \u06a9\u0633\u06cc \u06a9\u06cc \u0627\u0648\u0644\u0627\u062f \u06c1\u06d2\u06d4 \u0648\u06c1 \u0627\u06a9\u06cc\u0644\u0627 \u0645\u0639\u0628\u0648\u062f \u0628\u0631\u062d\u0642 \u0627\u0644\u0644\u06c1 \u06c1\u06d2\u06d4"
        }
]
