                "pashto": "\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u06cc \u0627\u0644\u0644\u0647 \u0639\u0644\u06cc\u0647 \u0648\u0633\u0644\u0645 \u062c\u0627\u0647\u0644\u0627\u0646\u0648 \u062a\u0647 \u0685\u0647 \u0648\u069a\u0648\u062f\u0644\u061f"
