      "longQuestions": [
        {
                "id": "cls2-ps-ch02-lq1",
                "question": "\u062f \u0644\u0648\u0633\u062a \"\u0646\u0639\u062a \u0631\u0633\u0648\u0644 \u0645\u0642\u0628\u0648\u0644 \ufdfa (\u0646\u0638\u0645)\" \u0644\u0646\u0689\u06cc\u0632 \u0627\u0648 \u0645\u0647\u0645 \u067c\u06a9\u064a \u067e\u0647 \u062e\u067e\u0644\u0648 \u067c\u06a9\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u06cc\u06a9\u0626.",
                "answer": "\u06c1\u0645\u0627\u0631\u06d2 \u067e\u06cc\u0627\u0631\u06d2 \u0646\u0628\u06cc \u062d\u0636\u0631\u062a \u0645\u062d\u0645\u062f \ufdfa \u06a9\u062a\u0646\u06d2 \u0639\u0638\u06cc\u0645 \u0627\u0633\u062a\u0627\u062f \u0627\u0648\u0631 \u0631\u06c1\u0628\u0631 \u06c1\u06cc\u06ba \u062c\u0646\u06c1\u0648\u06ba \u0646\u06d2 \u062c\u0627\u06c1\u0644\u0648\u06ba \u06a9\u0648 \u0639\u0627\u0644\u0645 \u0627\u0648\u0631 \u06a9\u0627\u0641\u0631\u0648\u06ba \u06a9\u0648 \u0645\u0648\u0645\u0646 \u0628\u0646\u0627 \u062f\u06cc\u0627\u06d4 \u0622\u067e\u0610 \u0646\u06d2 \u0633\u06cc\u062f\u06be\u0627 \u0631\u0627\u0633\u062a\u06c1 \u062f\u06a9\u06be\u0627\u06cc\u0627\u060c \u0627\u0646\u062f\u06be\u0648\u06ba \u06a9\u0627 \u0633\u06c1\u0627\u0631\u0627 \u0628\u0646\u06d2 \u0627\u0648\u0631 \u06c1\u0631 \u062f\u0631\u062f \u0645\u0646\u062f \u06a9\u06d2 \u062f\u06a9\u06be \u06a9\u06cc \u062f\u0648\u0627 \u0628\u0646\u06d2\u06d4 \u0685\u0648\u0645\u0631\u0647 \u069a\u06a9\u0644\u06d2 \u0645\u0639\u0644\u0645 \u062f\u06d2\n\u062c\u0627\u0647\u0644\u0627\u0646 \u0626\u06d0 \u0639\u0627\u0644\u0645\u0627\u0646 \u06a9\u0693\u0644\n\n\u0685\u0648\u0645\u0631\u0647 \u069a\u06a9\u0644\u06d2 \u0644\u0627\u0631 \u069a\u0627\u06cc\u0648\u0646\u06a9\u06d2\n\u06a9\u0627\u0641\u0631\u0627\u0646 \u0626\u06d0 \u0645\u0648\u0645\u0646\u0627\u0646 \u06a9\u0693\u0644\n\n\u0646\u06d0\u063a\u0647 \u0644\u0627\u0631 \u0626\u06d0 \u06a9\u0693\u0647 \u067e\u0647 \u06ab\u0648\u062a\u0647\n\u062f \u0693\u0646\u062f\u0648 \u062f \u0644\u0627\u0633 \u0627\u0645\u0633\u0627 \u0634\u0648\n\n\u06a9\u0647 \u0685\u0648\u06a9 \u06ab\u0648\u0689 \u0648\u0648 \u06a9\u0647 \u0685\u0648\u06a9 \u0634\u0644 \u0648\u0648\n\u062f \u0647\u0631 \u0686\u0627 \u062f \u062f\u0631\u062f \u062f\u0648\u0627 \u0634\u0648",
                "urdu": "\u0633\u0628\u0642 \"\u0646\u0639\u062a\u0650 \u0631\u0633\u0648\u0644\u0650 \u0645\u0642\u0628\u0648\u0644 \ufdfa (\u0646\u0638\u0645)\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u06c1\u0645\u0627\u0631\u06d2 \u067e\u06cc\u0627\u0631\u06d2 \u0646\u0628\u06cc \u062d\u0636\u0631\u062a \u0645\u062d\u0645\u062f \ufdfa \u06a9\u062a\u0646\u06d2 \u0639\u0638\u06cc\u0645 \u0627\u0633\u062a\u0627\u062f \u0627\u0648\u0631 \u0631\u06c1\u0628\u0631 \u06c1\u06cc\u06ba \u062c\u0646\u06c1\u0648\u06ba \u0646\u06d2 \u062c\u0627\u06c1\u0644\u0648\u06ba \u06a9\u0648 \u0639\u0627\u0644\u0645 \u0627\u0648\u0631 \u06a9\u0627\u0641\u0631\u0648\u06ba \u06a9\u0648 \u0645\u0648\u0645\u0646 \u0628\u0646\u0627 \u062f\u06cc\u0627\u06d4 \u0622\u067e\u0610 \u0646\u06d2 \u0633\u06cc\u062f\u06be\u0627 \u0631\u0627\u0633\u062a\u06c1 \u062f\u06a9\u06be\u0627\u06cc\u0627\u060c \u0627\u0646\u062f\u06be\u0648\u06ba \u06a9\u0627 \u0633\u06c1\u0627\u0631\u0627 \u0628\u0646\u06d2 \u0627\u0648\u0631 \u06c1\u0631 \u062f\u0631\u062f \u0645\u0646\u062f \u06a9\u06d2 \u062f\u06a9\u06be \u06a9\u06cc \u062f\u0648\u0627 \u0628\u0646\u06d2\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u062f\u0631\u0633 \u0645\u0647\u0645 \u067c\u06a9\u064a \u0648\u0644\u06cc\u06a9\u0626.",
                "pashtoAns": "\u0685\u0648\u0645\u0631\u0647 \u069a\u06a9\u0644\u06d2 \u0645\u0639\u0644\u0645 \u062f\u06d2\n\u062c\u0627\u0647\u0644\u0627\u0646 \u0626\u06d0 \u0639\u0627\u0644\u0645\u0627\u0646 \u06a9\u0693\u0644\n\n\u0685\u0648\u0645\u0631\u0647 \u069a\u06a9\u0644\u06d2 \u0644\u0627\u0631 \u069a\u0627\u06cc\u0648\u0646\u06a9\u06d2\n\u06a9\u0627\u0641\u0631\u0627\u0646 \u0626\u06d0 \u0645\u0648\u0645\u0646\u0627\u0646 \u06a9\u0693\u0644\n\n\u0646\u06d0\u063a\u0647 \u0644\u0627\u0631 \u0626\u06d0 \u06a9\u0693\u0647 \u067e\u0647 \u06ab\u0648\u062a\u0647\n\u062f \u0693\u0646\u062f\u0648 \u062f \u0644\u0627\u0633 \u0627\u0645\u0633\u0627 \u0634\u0648\n\n\u06a9\u0647 \u0685\u0648\u06a9 \u06ab\u0648\u0689 \u0648\u0648 \u06a9\u0647 \u0685\u0648\u06a9 \u0634\u0644 \u0648\u0648\n\u062f \u0647\u0631 \u0686\u0627 \u062f \u062f\u0631\u062f \u062f\u0648\u0627 \u0634\u0648"
        }
]
