      "longQuestions": [
        {
                "id": "cls2-ps-ch03-lq1",
                "question": "\u062f \u0644\u0648\u0633\u062a \"\u0632\u0645\u0648\u0646\u0696 \u067e\u06d0\u063a\u0645\u0628\u0631 \u062d\u0636\u0631\u062a \u0645\u062d\u0645\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\" \u0644\u0646\u0689\u06cc\u0632 \u0627\u0648 \u0645\u0647\u0645 \u067c\u06a9\u064a \u067e\u0647 \u062e\u067e\u0644\u0648 \u067c\u06a9\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u06cc\u06a9\u0626.",
                "answer": "\u06c1\u0645\u0627\u0631\u06d2 \u067e\u06cc\u0627\u0631\u06d2 \u0646\u0628\u06cc \u062d\u0636\u0631\u062a \u0645\u062d\u0645\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u06c1 \ufdfa \u0645\u06a9\u06c1 \u0645\u06a9\u0631\u0645\u06c1 \u0645\u06cc\u06ba \u067e\u06cc\u062f\u0627 \u06c1\u0648\u0626\u06d2\u06d4 \u0622\u067e\u0610 \u0628\u0686\u067e\u0646 \u06c1\u06cc \u0633\u06d2 \u0633\u0686\u06d2 \u0627\u0648\u0631 \u0627\u0645\u06cc\u0646 \u062a\u06be\u06d2\u06d4 \u0686\u0627\u0644\u06cc\u0633 \u0633\u0627\u0644 \u06a9\u06cc \u0639\u0645\u0631 \u0645\u06cc\u06ba \u0646\u0628\u0648\u062a \u0645\u0644\u06cc \u0627\u0648\u0631 \u0622\u067e\u0610 \u0646\u06d2 \u062f\u0646\u06cc\u0627 \u06a9\u0648 \u0627\u0645\u0646 \u0627\u0648\u0631 \u062a\u0648\u062d\u06cc\u062f \u06a9\u0627 \u062f\u0631\u0633 \u062f\u06cc\u0627\u06d4 \u0632\u0645\u0648\u0646\u0696 \u06ab\u0631\u0627\u0646 \u067e\u06cc\u063a\u0645\u0628\u0631 \u062d\u0636\u0631\u062a \u0645\u062d\u0645\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u062e\u0627\u062a\u0645 \u0627\u0644\u0646\u0628\u06cc\u06cc\u0646 \u0635\u0644\u06cc \u0627\u0644\u0644\u0647 \u0639\u0644\u06cc\u0647 \u0648\u0639\u0644\u06cc \u0622\u0644\u0647 \u0648\u0627\u0635\u062d\u0627\u0628\u0647 \u0648\u0633\u0644\u0645 \u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u06cc \u0622\u062e\u0631\u064a \u0631\u0633\u0648\u0644 \u062f\u06cc.\n\n\u0647\u063a\u0647 \u0645\u0628\u0627\u0631\u06a9 \u067e\u0647 \u0645\u06a9\u0647 \u0645\u06a9\u0631\u0645\u0647 \u06a9\u069a\u06d0 \u067e\u06cc\u062f\u0627 \u0634\u0648. \u062f \u067e\u0644\u0627\u0631 \u0646\u0648\u0645 \u06cc\u06d0 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0627\u0648 \u062f \u0645\u0648\u0631 \u0646\u0648\u0645 \u06cc\u06d0 \u0628\u064a \u0628\u064a \u0622\u0645\u0646\u0647 \u0648\u0647. \u0647\u063a\u0647 \u0645\u0628\u0627\u0631\u06a9 \u0644\u0647 \u0645\u0627\u0634\u0648\u0645\u062a\u0648\u0628\u0647 \u0689\u06d0\u0631 \u0631\u069a\u062a\u06cc\u0646\u06cc \u0627\u0648 \u0627\u0645\u0627\u0646\u062a \u062f\u0627\u0631 \u0648\u060c \u0681\u06a9\u0647 \u062e\u0644\u06a9\u0648 \u0648\u0631\u062a\u0647 \u0635\u0627\u062f\u0642 \u0627\u0648 \u0627\u0645\u06cc\u0646 \u0648\u0627\u06cc\u0647.\n\n\u06a9\u0644\u0647 \u0686\u06d0 \u0685\u0644\u0648\u06d0\u069a\u062a \u06a9\u0644\u0646 \u0634\u0648 \u0646\u0648 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u06cc \u067e\u0631\u06d0 \u0648\u062d\u064a \u0627\u0648 \u0646\u0628\u0648\u062a \u0646\u0627\u0632\u0644 \u06a9\u0693. \u0647\u063a\u0647 \u0645\u0628\u0627\u0631\u06a9 \u067c\u0648\u0644\u0648 \u0627\u0646\u0633\u0627\u0646\u0627\u0646\u0648 \u062a\u0647 \u062f \u0646\u06d0\u06a9\u06cd\u060c \u0633\u0648\u0644\u06d0\u060c \u062f \u06cc\u0648 \u0627\u0644\u0644\u0647 \u062f \u0639\u0628\u0627\u062f\u062a \u0627\u0648 \u062f \u069a\u0648 \u0627\u062e\u0644\u0627\u0642\u0648 \u0628\u0644\u0646\u0647 \u0648\u0631\u06a9\u0693\u0647.",
                "urdu": "\u0633\u0628\u0642 \"\u06c1\u0645\u0627\u0631\u06d2 \u067e\u06cc\u063a\u0645\u0628\u0631 \u062d\u0636\u0631\u062a \u0645\u062d\u0645\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u06c1 \ufdfa\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u06c1\u0645\u0627\u0631\u06d2 \u067e\u06cc\u0627\u0631\u06d2 \u0646\u0628\u06cc \u062d\u0636\u0631\u062a \u0645\u062d\u0645\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u06c1 \ufdfa \u0645\u06a9\u06c1 \u0645\u06a9\u0631\u0645\u06c1 \u0645\u06cc\u06ba \u067e\u06cc\u062f\u0627 \u06c1\u0648\u0626\u06d2\u06d4 \u0622\u067e\u0610 \u0628\u0686\u067e\u0646 \u06c1\u06cc \u0633\u06d2 \u0633\u0686\u06d2 \u0627\u0648\u0631 \u0627\u0645\u06cc\u0646 \u062a\u06be\u06d2\u06d4 \u0686\u0627\u0644\u06cc\u0633 \u0633\u0627\u0644 \u06a9\u06cc \u0639\u0645\u0631 \u0645\u06cc\u06ba \u0646\u0628\u0648\u062a \u0645\u0644\u06cc \u0627\u0648\u0631 \u0622\u067e\u0610 \u0646\u06d2 \u062f\u0646\u06cc\u0627 \u06a9\u0648 \u0627\u0645\u0646 \u0627\u0648\u0631 \u062a\u0648\u062d\u06cc\u062f \u06a9\u0627 \u062f\u0631\u0633 \u062f\u06cc\u0627\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u062f\u0631\u0633 \u0645\u0647\u0645 \u067c\u06a9\u064a \u0648\u0644\u06cc\u06a9\u0626.",
                "pashtoAns": "\u0632\u0645\u0648\u0646\u0696 \u06ab\u0631\u0627\u0646 \u067e\u06cc\u063a\u0645\u0628\u0631 \u062d\u0636\u0631\u062a \u0645\u062d\u0645\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u062e\u0627\u062a\u0645 \u0627\u0644\u0646\u0628\u06cc\u06cc\u0646 \u0635\u0644\u06cc \u0627\u0644\u0644\u0647 \u0639\u0644\u06cc\u0647 \u0648\u0639\u0644\u06cc \u0622\u0644\u0647 \u0648\u0627\u0635\u062d\u0627\u0628\u0647 \u0648\u0633\u0644\u0645 \u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u06cc \u0622\u062e\u0631\u064a \u0631\u0633\u0648\u0644 \u062f\u06cc.\n\n\u0647\u063a\u0647 \u0645\u0628\u0627\u0631\u06a9 \u067e\u0647 \u0645\u06a9\u0647 \u0645\u06a9\u0631\u0645\u0647 \u06a9\u069a\u06d0 \u067e\u06cc\u062f\u0627 \u0634\u0648. \u062f \u067e\u0644\u0627\u0631 \u0646\u0648\u0645 \u06cc\u06d0 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0627\u0648 \u062f \u0645\u0648\u0631 \u0646\u0648\u0645 \u06cc\u06d0 \u0628\u064a \u0628\u064a \u0622\u0645\u0646\u0647 \u0648\u0647. \u0647\u063a\u0647 \u0645\u0628\u0627\u0631\u06a9 \u0644\u0647 \u0645\u0627\u0634\u0648\u0645\u062a\u0648\u0628\u0647 \u0689\u06d0\u0631 \u0631\u069a\u062a\u06cc\u0646\u06cc \u0627\u0648 \u0627\u0645\u0627\u0646\u062a \u062f\u0627\u0631 \u0648\u060c \u0681\u06a9\u0647 \u062e\u0644\u06a9\u0648 \u0648\u0631\u062a\u0647 \u0635\u0627\u062f\u0642 \u0627\u0648 \u0627\u0645\u06cc\u0646 \u0648\u0627\u06cc\u0647.\n\n\u06a9\u0644\u0647 \u0686\u06d0 \u0685\u0644\u0648\u06d0\u069a\u062a \u06a9\u0644\u0646 \u0634\u0648 \u0646\u0648 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u06cc \u067e\u0631\u06d0 \u0648\u062d\u064a \u0627\u0648 \u0646\u0628\u0648\u062a \u0646\u0627\u0632\u0644 \u06a9\u0693. \u0647\u063a\u0647 \u0645\u0628\u0627\u0631\u06a9 \u067c\u0648\u0644\u0648 \u0627\u0646\u0633\u0627\u0646\u0627\u0646\u0648 \u062a\u0647 \u062f \u0646\u06d0\u06a9\u06cd\u060c \u0633\u0648\u0644\u06d0\u060c \u062f \u06cc\u0648 \u0627\u0644\u0644\u0647 \u062f \u0639\u0628\u0627\u062f\u062a \u0627\u0648 \u062f \u069a\u0648 \u0627\u062e\u0644\u0627\u0642\u0648 \u0628\u0644\u0646\u0647 \u0648\u0631\u06a9\u0693\u0647."
        }
]
