                "urdu": "\u0627\u0633 \u06a9\u06c1\u0627\u0646\u06cc \u06a9\u0627 \u0633\u0628\u0642 \u06a9\u06cc\u0627 \u06c1\u06d2\u061f",
                "pashto": "\u0644\u0647 \u062f\u06d0 \u06a9\u06cc\u0633\u06d0 \u0645\u0648\u0696 \u0685\u0647 \u0632\u062f\u0647 \u06a9\u0648\u0648\u061f"
