                "q": "\u062f \u062f\u06d0 \u0644\u0648\u0633\u062a \u0627\u062e\u0644\u0627\u0642\u064a \u0627\u0648 \u069a\u0648\u0648\u0646\u06cc\u0632 \u067e\u06cc\u063a\u0627\u0645 \u0685\u0647 \u062f\u06cc\u061f",
                "ans": "\u0627\u06cc\u06a9 \u063a\u0631\u06cc\u0628 \u0627\u06cc\u0645\u0627\u0646\u062f\u0627\u0631 \u0634\u062e\u0635 \u06a9\u0648 \u0633\u0648\u0646\u06d2 \u06a9\u0627 \u0642\u06cc\u0645\u062a\u06cc \u06c1\u0627\u0631 \u0645\u0644\u0627\u06d4 \u0627\u0633 \u0646\u06d2 \u0644\u0627\u0644\u0686 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06d2 \u0627\u0639\u0644\u0627\u0646 \u06a9\u0631\u0627 \u06a9\u06d2 \u0627\u0635\u0644 \u0645\u0627\u0644\u06a9 \u06a9\u06d2 \u062d\u0648\u0627\u0644\u06d2 \u06a9\u0631 \u062f\u06cc\u0627\u06d4 \u0645\u0627\u0644\u06a9 \u0646\u06d2 \u0627\u0633 \u06a9\u06cc \u0627\u06cc\u0645\u0627\u0646\u062f\u0627\u0631\u06cc \u067e\u0631 \u0627\u0633\u06d2 \u0627\u0646\u0639\u0627\u0645 \u062f\u06cc\u0627\u06d4 \u0627\u06cc\u0645\u0627\u0646\u062f\u0627\u0631\u06cc \u06a9\u0627 \u067e\u06be\u0644 \u06c1\u0645\u06cc\u0634\u06c1 \u0645\u06cc\u0679\u06be\u0627 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4"
