      "longQuestions": [
        {
                "id": "cls2-ps-ch05-lq1",
                "question": "\u062f \u0644\u0648\u0633\u062a \"\u062f \u0645\u0627\u0634\u0648\u0645\u0627\u0646\u0648 \u0633\u0646\u062f\u0631\u06d0 (\u0646\u0638\u0645)\" \u0644\u0646\u0689\u06cc\u0632 \u0627\u0648 \u0645\u0647\u0645 \u067c\u06a9\u064a \u067e\u0647 \u062e\u067e\u0644\u0648 \u067c\u06a9\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u06cc\u06a9\u0626.",
                "answer": "\u0628\u0686\u06d2 \u0645\u0644 \u062c\u0644 \u06a9\u0631 \u06a9\u06be\u06cc\u0644\u0646\u06d2\u060c \u0634\u0648\u0642 \u0633\u06d2 \u0633\u06a9\u0648\u0644 \u062c\u0627\u0646\u06d2 \u0627\u0648\u0631 \u062e\u0648\u0628 \u067e\u0691\u06be\u0646\u06d2 \u06a9\u0627 \u0639\u0632\u0645 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0628\u0686\u06d2 \u0648\u0637\u0646 \u06a9\u0627 \u0645\u0633\u062a\u0642\u0628\u0644 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u0639\u0644\u0645 \u06a9\u06cc \u0631\u0648\u0634\u0646\u06cc \u0633\u06d2 \u0627\u067e\u0646\u06d2 \u067e\u06cc\u0627\u0631\u06d2 \u0648\u0637\u0646 \u06a9\u0648 \u062e\u0648\u0628\u0635\u0648\u0631\u062a \u0628\u0627\u063a \u0628\u0646\u0627\u0626\u06cc\u06ba \u06af\u06d2\u06d4 \u0631\u0627\u0634\u0626 \u0645\u0644\u06ab\u0631\u0648 \u0631\u0627\u0634\u0626\n\u067e\u0647 \u06ab\u0689\u0647 \u0628\u0647 \u0644\u0648\u0628\u06d0 \u0648\u06a9\u0693\u0648\n\n\u069a\u0648\u0648\u0646\u0681\u064a \u062a\u0647 \u0628\u0647 \u0681\u0648 \u067e\u0647 \u0645\u06cc\u0646\u0647\n\u0644\u0648\u0633\u062a \u0628\u0647 \u067e\u0647 \u0634\u0648\u0642 \u0632\u062f\u0647 \u06a9\u0693\u0648\n\n\u062e\u067e\u0644 \u0648\u0637\u0646 \u0628\u0647 \u0648\u062f\u0627\u0646 \u06a9\u0693\u0648\n\u062f \u0639\u0644\u0645 \u0631\u06bc\u0627 \u0628\u0647 \u062e\u067e\u0631\u0647 \u06a9\u0693\u0648\n\n\u0645\u0648\u0696 \u062f \u0648\u0637\u0646 \u0633\u0628\u0627\u0648\u0648\u0646 \u06cc\u0648\n\u062e\u067e\u0644 \u0647\u06d0\u0648\u0627\u062f \u0628\u0647 \u06ab\u0644\u0633\u062a\u0627\u0646 \u06a9\u0693\u0648",
                "urdu": "\u0633\u0628\u0642 \"\u0628\u0686\u0648\u06ba \u06a9\u06d2 \u06af\u06cc\u062a (\u0646\u0638\u0645)\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0628\u0686\u06d2 \u0645\u0644 \u062c\u0644 \u06a9\u0631 \u06a9\u06be\u06cc\u0644\u0646\u06d2\u060c \u0634\u0648\u0642 \u0633\u06d2 \u0633\u06a9\u0648\u0644 \u062c\u0627\u0646\u06d2 \u0627\u0648\u0631 \u062e\u0648\u0628 \u067e\u0691\u06be\u0646\u06d2 \u06a9\u0627 \u0639\u0632\u0645 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0628\u0686\u06d2 \u0648\u0637\u0646 \u06a9\u0627 \u0645\u0633\u062a\u0642\u0628\u0644 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u0639\u0644\u0645 \u06a9\u06cc \u0631\u0648\u0634\u0646\u06cc \u0633\u06d2 \u0627\u067e\u0646\u06d2 \u067e\u06cc\u0627\u0631\u06d2 \u0648\u0637\u0646 \u06a9\u0648 \u062e\u0648\u0628\u0635\u0648\u0631\u062a \u0628\u0627\u063a \u0628\u0646\u0627\u0626\u06cc\u06ba \u06af\u06d2\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u062f\u0631\u0633 \u0645\u0647\u0645 \u067c\u06a9\u064a \u0648\u0644\u06cc\u06a9\u0626.",
                "pashtoAns": "\u0631\u0627\u0634\u0626 \u0645\u0644\u06ab\u0631\u0648 \u0631\u0627\u0634\u0626\n\u067e\u0647 \u06ab\u0689\u0647 \u0628\u0647 \u0644\u0648\u0628\u06d0 \u0648\u06a9\u0693\u0648\n\n\u069a\u0648\u0648\u0646\u0681\u064a \u062a\u0647 \u0628\u0647 \u0681\u0648 \u067e\u0647 \u0645\u06cc\u0646\u0647\n\u0644\u0648\u0633\u062a \u0628\u0647 \u067e\u0647 \u0634\u0648\u0642 \u0632\u062f\u0647 \u06a9\u0693\u0648\n\n\u062e\u067e\u0644 \u0648\u0637\u0646 \u0628\u0647 \u0648\u062f\u0627\u0646 \u06a9\u0693\u0648\n\u062f \u0639\u0644\u0645 \u0631\u06bc\u0627 \u0628\u0647 \u062e\u067e\u0631\u0647 \u06a9\u0693\u0648\n\n\u0645\u0648\u0696 \u062f \u0648\u0637\u0646 \u0633\u0628\u0627\u0648\u0648\u0646 \u06cc\u0648\n\u062e\u067e\u0644 \u0647\u06d0\u0648\u0627\u062f \u0628\u0647 \u06ab\u0644\u0633\u062a\u0627\u0646 \u06a9\u0693\u0648"
        }
]
