                "question": "\u062d\u062f\u06cc\u062b \u0645\u0628\u0627\u0631\u06a9 \u062f \u0645\u0634\u0631\u0627\u0646\u0648 \u067e\u0647 \u0647\u06a9\u0644\u0647 \u0685\u0647 \u0648\u0627\u064a\u064a\u061f",
                "answer": "\u0686\u06d0 \u062f \u0645\u0634\u0631\u0627\u0646\u0648 \u0642\u062f\u0631 \u0627\u0648 \u062f\u0631\u0646\u0627\u0648\u06cc \u067e\u06d0\u0698\u0646\u062f\u0644 \u0644\u0627\u0632\u0645 \u062f\u064a.",
                "urdu": "\u062d\u062f\u06cc\u062b \u0645\u06cc\u06ba \u06a9\u06cc\u0627 \u0641\u0631\u0645\u0627\u06cc\u0627 \u06af\u06cc\u0627\u061f",
                "pashto": "\u062d\u062f\u06cc\u062b \u0645\u0628\u0627\u0631\u06a9 \u062f \u0645\u0634\u0631\u0627\u0646\u0648 \u067e\u0647 \u0647\u06a9\u0644\u0647 \u0685\u0647 \u0648\u0627\u064a\u064a\u061f",
                "pashtoAns": "\u062f \u0645\u0634\u0631\u0627\u0646\u0648 \u0642\u062f\u0631 \u067e\u06d0\u0698\u0646\u062f\u0644 \u062f \u0645\u0633\u0644\u0645\u0627\u0646 \u0646\u069a\u0647 \u062f\u0647."
