                "answer": "\u0633\u067e\u064a \u067e\u0647 \u0627\u0648\u0628\u0648 \u06a9\u069a\u06d0 \u062e\u067e\u0644 \u0633\u06cc\u0648\u0631\u06cc \u0648\u0644\u06cc\u062f.",
                "urdu": "\u06a9\u062a\u06d2 \u0646\u06d2 \u067e\u0627\u0646\u06cc \u0645\u06cc\u06ba \u06a9\u06cc\u0627 \u062f\u06cc\u06a9\u06be\u0627\u061f",
