      "longQuestions": [
        {
                "id": "cls2-ps-ch08-lq1",
                "question": "\u062f \u0644\u0648\u0633\u062a \"\u062f \u063a\u0648\u069a\u06d0 \u067e\u0648\u067c\u06d2\" \u0644\u0646\u0689\u06cc\u0632 \u0627\u0648 \u0645\u0647\u0645 \u067c\u06a9\u064a \u067e\u0647 \u062e\u067e\u0644\u0648 \u067c\u06a9\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u06cc\u06a9\u0626.",
                "answer": "\u0627\u06cc\u06a9 \u0644\u0627\u0644\u0686\u06cc \u06a9\u062a\u06d2 \u0646\u06d2 \u067e\u0644 \u067e\u0631 \u067e\u0627\u0646\u06cc \u0645\u06cc\u06ba \u0627\u067e\u0646\u0627 \u0639\u06a9\u0633 \u062f\u06cc\u06a9\u06be\u0627 \u0627\u0648\u0631 \u0633\u0645\u062c\u06be\u0627 \u06a9\u06c1 \u062f\u0648\u0633\u0631\u0627 \u06a9\u062a\u0627 \u06af\u0648\u0634\u062a \u0644\u06cc\u06d2 \u06a9\u06be\u0691\u0627 \u06c1\u06d2\u06d4 \u0627\u0633 \u0646\u06d2 \u0628\u06be\u0648\u0646\u06a9\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0645\u0646\u06c1 \u06a9\u06be\u0648\u0644\u0627 \u062a\u0648 \u0627\u067e\u0646\u0627 \u06af\u0648\u0634\u062a \u0628\u06be\u06cc \u06af\u0646\u0648\u0627 \u0628\u06cc\u0679\u06be\u0627\u06d4 \u0644\u0627\u0644\u0686 \u0628\u0631\u06cc \u0628\u0644\u0627 \u06c1\u06d2\u06d4 \u06cc\u0648 \u0633\u067e\u06cc \u0631\u0648\u0627\u0646 \u0648 \u0686\u06d0 \u062f \u0642\u0635\u0627\u0628 \u0644\u0647 \u062f\u0648\u06a9\u0627\u0646\u0647 \u06cc\u06d0 \u062f \u063a\u0648\u069a\u06d0 \u06cc\u0648 \u067e\u0648\u067c\u06cc \u0648\u0645\u0648\u0646\u062f. \u0633\u067e\u06cc \u0689\u06d0\u0631 \u062e\u0648\u0634\u062d\u0627\u0644\u0647 \u0634\u0648 \u0627\u0648 \u062f \u063a\u0648\u069a\u06d0 \u067e\u0648\u067c\u06cc \u06cc\u06d0 \u067e\u0647 \u062e\u0648\u0644\u0647 \u06a9\u069a\u06d0 \u0648\u0646\u06cc\u0648\u0647 \u0627\u0648 \u062f \u0681\u0646\u06ab\u0644 \u0644\u0648\u0631 \u062a\u0647 \u0631\u0648\u0627\u0646 \u0634\u0648.\n\n\u067e\u0647 \u0644\u0627\u0631\u0647 \u06a9\u069a\u06d0 \u062f \u0627\u0648\u0628\u0648 \u06cc\u0648 \u067e\u0648\u0644 (\u067e\u064f\u0644) \u0648. \u06a9\u0644\u0647 \u0686\u06d0 \u0633\u067e\u064a \u0644\u0647 \u067e\u0644\u0647 \u0646\u0647 \u0644\u0627\u0646\u062f\u06d0 \u0635\u0627\u0641\u0648 \u0627\u0648\u0628\u0648 \u062a\u0647 \u0648\u06a9\u062a\u0644\u060c \u0646\u0648 \u062e\u067e\u0644 \u0633\u06cc\u0648\u0631\u06cc \u06cc\u06d0 \u0648\u0644\u06cc\u062f. \u0647\u063a\u0647 \u0641\u06a9\u0631 \u0648\u06a9\u0693 \u0686\u06d0 \u0628\u0644 \u0633\u067e\u06cc \u062f\u06cc \u0627\u0648 \u062f \u0647\u063a\u0647 \u067e\u0647 \u062e\u0648\u0644\u0647 \u06a9\u069a\u06d0 \u0647\u0645 \u062f \u063a\u0648\u069a\u06d0 \u067e\u0648\u067c\u06cc \u062f\u06cc.\n\n\u0644\u0627\u0644\u0686\u064a \u0633\u067e\u064a \u063a\u0648\u069a\u062a\u0644 \u0686\u06d0 \u0647\u063a\u0647 \u067e\u0648\u067c\u06cc \u0647\u0645 \u062a\u0631\u06d0 \u0648\u0627\u062e\u0644\u064a. \u0644\u06a9\u0647 \u0685\u0646\u06ab\u0647 \u0686\u06d0 \u06cc\u06d0 \u062e\u0648\u0644\u0647 \u062e\u0644\u0627\u0635\u0647 \u06a9\u0693\u0647 \u0686\u06d0 \u063a\u067e \u0648\u06a9\u0693\u064a\u060c \u0646\u0648 \u062e\u067e\u0644 \u062f \u063a\u0648\u069a\u06d0 \u067e\u0648\u067c\u06cc \u06cc\u06d0 \u0644\u0647 \u062e\u0648\u0644\u06d0 \u0646\u0647 \u067e\u0647 \u0627\u0648\u0628\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u0648\u06d0\u062f \u0627\u0648 \u0627\u0648\u0628\u0648 \u06cc\u0648\u0648\u0693. \u0633\u067e\u06cc \u062a\u0634\u0647 \u062e\u0648\u0644\u0647 \u0627\u0648 \u0648\u0696\u06cc \u067e\u0627\u062a\u06d0 \u0634\u0648. \u067e\u0627\u06cc\u0644\u0647: \u0644\u0627\u0644\u0686 \u0628\u062f \u0628\u0644\u0627 \u062f\u0647.",
                "urdu": "\u0633\u0628\u0642 \"\u06af\u0648\u0634\u062a \u06a9\u0627 \u0679\u06a9\u0691\u0627 (\u0644\u0627\u0644\u0686\u06cc \u06a9\u062a\u06d2 \u06a9\u06cc \u06a9\u06c1\u0627\u0646\u06cc)\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0627\u06cc\u06a9 \u0644\u0627\u0644\u0686\u06cc \u06a9\u062a\u06d2 \u0646\u06d2 \u067e\u0644 \u067e\u0631 \u067e\u0627\u0646\u06cc \u0645\u06cc\u06ba \u0627\u067e\u0646\u0627 \u0639\u06a9\u0633 \u062f\u06cc\u06a9\u06be\u0627 \u0627\u0648\u0631 \u0633\u0645\u062c\u06be\u0627 \u06a9\u06c1 \u062f\u0648\u0633\u0631\u0627 \u06a9\u062a\u0627 \u06af\u0648\u0634\u062a \u0644\u06cc\u06d2 \u06a9\u06be\u0691\u0627 \u06c1\u06d2\u06d4 \u0627\u0633 \u0646\u06d2 \u0628\u06be\u0648\u0646\u06a9\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0645\u0646\u06c1 \u06a9\u06be\u0648\u0644\u0627 \u062a\u0648 \u0627\u067e\u0646\u0627 \u06af\u0648\u0634\u062a \u0628\u06be\u06cc \u06af\u0646\u0648\u0627 \u0628\u06cc\u0679\u06be\u0627\u06d4 \u0644\u0627\u0644\u0686 \u0628\u0631\u06cc \u0628\u0644\u0627 \u06c1\u06d2\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u062f\u0631\u0633 \u0645\u0647\u0645 \u067c\u06a9\u064a \u0648\u0644\u06cc\u06a9\u0626.",
                "pashtoAns": "\u06cc\u0648 \u0633\u067e\u06cc \u0631\u0648\u0627\u0646 \u0648 \u0686\u06d0 \u062f \u0642\u0635\u0627\u0628 \u0644\u0647 \u062f\u0648\u06a9\u0627\u0646\u0647 \u06cc\u06d0 \u062f \u063a\u0648\u069a\u06d0 \u06cc\u0648 \u067e\u0648\u067c\u06cc \u0648\u0645\u0648\u0646\u062f. \u0633\u067e\u06cc \u0689\u06d0\u0631 \u062e\u0648\u0634\u062d\u0627\u0644\u0647 \u0634\u0648 \u0627\u0648 \u062f \u063a\u0648\u069a\u06d0 \u067e\u0648\u067c\u06cc \u06cc\u06d0 \u067e\u0647 \u062e\u0648\u0644\u0647 \u06a9\u069a\u06d0 \u0648\u0646\u06cc\u0648\u0647 \u0627\u0648 \u062f \u0681\u0646\u06ab\u0644 \u0644\u0648\u0631 \u062a\u0647 \u0631\u0648\u0627\u0646 \u0634\u0648.\n\n\u067e\u0647 \u0644\u0627\u0631\u0647 \u06a9\u069a\u06d0 \u062f \u0627\u0648\u0628\u0648 \u06cc\u0648 \u067e\u0648\u0644 (\u067e\u064f\u0644) \u0648. \u06a9\u0644\u0647 \u0686\u06d0 \u0633\u067e\u064a \u0644\u0647 \u067e\u0644\u0647 \u0646\u0647 \u0644\u0627\u0646\u062f\u06d0 \u0635\u0627\u0641\u0648 \u0627\u0648\u0628\u0648 \u062a\u0647 \u0648\u06a9\u062a\u0644\u060c \u0646\u0648 \u062e\u067e\u0644 \u0633\u06cc\u0648\u0631\u06cc \u06cc\u06d0 \u0648\u0644\u06cc\u062f. \u0647\u063a\u0647 \u0641\u06a9\u0631 \u0648\u06a9\u0693 \u0686\u06d0 \u0628\u0644 \u0633\u067e\u06cc \u062f\u06cc \u0627\u0648 \u062f \u0647\u063a\u0647 \u067e\u0647 \u062e\u0648\u0644\u0647 \u06a9\u069a\u06d0 \u0647\u0645 \u062f \u063a\u0648\u069a\u06d0 \u067e\u0648\u067c\u06cc \u062f\u06cc.\n\n\u0644\u0627\u0644\u0686\u064a \u0633\u067e\u064a \u063a\u0648\u069a\u062a\u0644 \u0686\u06d0 \u0647\u063a\u0647 \u067e\u0648\u067c\u06cc \u0647\u0645 \u062a\u0631\u06d0 \u0648\u0627\u062e\u0644\u064a. \u0644\u06a9\u0647 \u0685\u0646\u06ab\u0647 \u0686\u06d0 \u06cc\u06d0 \u062e\u0648\u0644\u0647 \u062e\u0644\u0627\u0635\u0647 \u06a9\u0693\u0647 \u0686\u06d0 \u063a\u067e \u0648\u06a9\u0693\u064a\u060c \u0646\u0648 \u062e\u067e\u0644 \u062f \u063a\u0648\u069a\u06d0 \u067e\u0648\u067c\u06cc \u06cc\u06d0 \u0644\u0647 \u062e\u0648\u0644\u06d0 \u0646\u0647 \u067e\u0647 \u0627\u0648\u0628\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u0648\u06d0\u062f \u0627\u0648 \u0627\u0648\u0628\u0648 \u06cc\u0648\u0648\u0693. \u0633\u067e\u06cc \u062a\u0634\u0647 \u062e\u0648\u0644\u0647 \u0627\u0648 \u0648\u0696\u06cc \u067e\u0627\u062a\u06d0 \u0634\u0648. \u067e\u0627\u06cc\u0644\u0647: \u0644\u0627\u0644\u0686 \u0628\u062f \u0628\u0644\u0627 \u062f\u0647."
        }
]
