                "q": "\u062f \u062f\u06d0 \u0644\u0648\u0633\u062a \u0627\u062e\u0644\u0627\u0642\u064a \u0627\u0648 \u069a\u0648\u0648\u0646\u06cc\u0632 \u067e\u06cc\u063a\u0627\u0645 \u0685\u0647 \u062f\u06cc\u061f",
                "ans": "\u0627\u06cc\u06a9 \u0644\u0627\u0644\u0686\u06cc \u06a9\u062a\u06d2 \u0646\u06d2 \u067e\u0644 \u067e\u0631 \u067e\u0627\u0646\u06cc \u0645\u06cc\u06ba \u0627\u067e\u0646\u0627 \u0639\u06a9\u0633 \u062f\u06cc\u06a9\u06be\u0627 \u0627\u0648\u0631 \u0633\u0645\u062c\u06be\u0627 \u06a9\u06c1 \u062f\u0648\u0633\u0631\u0627 \u06a9\u062a\u0627 \u06af\u0648\u0634\u062a \u0644\u06cc\u06d2 \u06a9\u06be\u0691\u0627 \u06c1\u06d2\u06d4 \u0627\u0633 \u0646\u06d2 \u0628\u06be\u0648\u0646\u06a9\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0645\u0646\u06c1 \u06a9\u06be\u0648\u0644\u0627 \u062a\u0648 \u0627\u067e\u0646\u0627 \u06af\u0648\u0634\u062a \u0628\u06be\u06cc \u06af\u0646\u0648\u0627 \u0628\u06cc\u0679\u06be\u0627\u06d4 \u0644\u0627\u0644\u0686 \u0628\u0631\u06cc \u0628\u0644\u0627 \u06c1\u06d2\u06d4"
