                "correct": 0,
                "explanation": "\u0681\u06a9\u0647 \u0686\u06d0 \u0634\u067e\u0647 \u0634\u0648\u0647 \u0627\u0648 \u067e\u0647 \u062a\u06cc\u0627\u0631\u0647 \u06a9\u06d0 \u06cc\u06d0 \u062e\u067e\u0644\u0647 \u0681\u0627\u0644\u0647 \u0646\u0647 \u0645\u0648\u0646\u062f\u0644\u0647.",
                "urdu": "\u0628\u0644\u0628\u0644 \u06a9\u06cc\u0648\u06ba \u0627\u062f\u0627\u0633 \u062a\u06be\u0627\u061f",
                "pashto": "\u0628\u0644\u0628\u0644 \u0648\u0644\u06d0 \u062e\u067e\u0647 \u0648\u061f"
