      "shortQuestions": [
        {
                "id": "cls2-ps-ch09-sq1",
                "question": "\u0628\u0644\u0628\u0644 \u0648\u0644\u06d0 \u062e\u067e\u0647 \u0648\u061f",
                "answer": "\u0681\u06a9\u0647 \u0686\u06d0 \u0634\u067e\u0647 \u0634\u0648\u0647 \u0627\u0648 \u067e\u0647 \u062a\u06cc\u0627\u0631\u0647 \u06a9\u06d0 \u06cc\u06d0 \u062e\u067e\u0644\u0647 \u0681\u0627\u0644\u0647 \u0646\u0647 \u0645\u0648\u0646\u062f\u0644\u0647.",
                "urdu": "\u0628\u0644\u0628\u0644 \u06a9\u06cc\u0648\u06ba \u0627\u062f\u0627\u0633 \u062a\u06be\u0627\u061f",
                "pashto": "\u0628\u0644\u0628\u0644 \u0648\u0644\u06d0 \u062e\u067e\u0647 \u0648\u061f",
                "pashtoAns": "\u0681\u06a9\u0647 \u0686\u06d0 \u062a\u06cc\u0627\u0631\u0647 \u0634\u0648\u0647 \u0627\u0648 \u0681\u0627\u0644\u0647 \u062a\u0631\u06d0 \u0648\u0631\u06a9\u0647 \u0634\u0648\u0647."
        },
        {
                "id": "cls2-ps-ch09-sq2",
                "question": "\u067e\u062a\u0646\u06ab (\u062c\u06af\u0646\u0648) \u0628\u0644\u0628\u0644 \u062a\u0647 \u0685\u0646\u06ab\u0647 \u0645\u0631\u0633\u062a\u0647 \u0648\u06a9\u0693\u0647\u061f",
                "answer": "\u067e\u062a\u0646\u06ab \u062e\u067e\u0644\u0647 \u0631\u06bc\u0627 \u0648\u069a\u0648\u062f\u0644\u0647 \u0627\u0648 \u062f \u0628\u0644\u0628\u0644 \u0644\u0627\u0631 \u06cc\u06d0 \u0631\u0648\u069a\u0627\u0646\u0647 \u06a9\u0693\u0647.",
                "urdu": "\u062c\u06af\u0646\u0648 \u0646\u06d2 \u0628\u0644\u0628\u0644 \u06a9\u06cc \u0645\u062f\u062f \u06a9\u06cc\u0633\u06d2 \u06a9\u06cc\u061f",
                "pashto": "\u067e\u062a\u0646\u06ab (\u062c\u06af\u0646\u0648) \u0628\u0644\u0628\u0644 \u062a\u0647 \u0685\u0646\u06ab\u0647 \u0645\u0631\u0633\u062a\u0647 \u0648\u06a9\u0693\u0647\u061f",
                "pashtoAns": "\u062e\u067e\u0644\u0647 \u0631\u06bc\u0627 \u06cc\u06d0 \u062f \u0644\u0627\u0631\u06d0 \u0645\u0634\u0627\u0644 \u06a9\u0693\u0647."
        }
],
      "longQuestions": [
        {
                "id": "cls2-ps-ch09-lq1",
                "question": "\u062f \u0644\u0648\u0633\u062a \"\u0647\u0645\u062f\u0631\u062f\u064a (\u0646\u0638\u0645)\" \u0644\u0646\u0689\u06cc\u0632 \u0627\u0648 \u0645\u0647\u0645 \u067c\u06a9\u064a \u067e\u0647 \u062e\u067e\u0644\u0648 \u067c\u06a9\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u06cc\u06a9\u0626.",
                "answer": "\u0639\u0644\u0627\u0645\u06c1 \u0627\u0642\u0628\u0627\u0644 \u06a9\u06cc \u0645\u0634\u06c1\u0648\u0631 \u0646\u0638\u0645 '\u06c1\u0645\u062f\u0631\u062f\u06cc' \u06a9\u0627 \u067e\u0634\u062a\u0648 \u0646\u062b\u0631\u06cc \u0648 \u0645\u0646\u0638\u0648\u0645 \u0645\u0641\u06c1\u0648\u0645\u06d4 \u0627\u06cc\u06a9 \u0646\u0646\u06be\u06d2 \u062c\u06af\u0646\u0648 \u0646\u06d2 \u0627\u0646\u062f\u06be\u06cc\u0631\u06cc \u0631\u0627\u062a \u0645\u06cc\u06ba \u067e\u0631\u06cc\u0634\u0627\u0646 \u0628\u0644\u0628\u0644 \u06a9\u0648 \u0627\u067e\u0646\u06cc \u0631\u0648\u0634\u0646\u06cc \u067e\u06cc\u0634 \u06a9\u06cc \u062a\u0627\u06a9\u06c1 \u0648\u06c1 \u0627\u067e\u0646\u06d2 \u06af\u06be\u0648\u0646\u0633\u0644\u06d2 \u062a\u06a9 \u067e\u06c1\u0646\u0686 \u0633\u06a9\u06d2\u06d4 \u0633\u0686\u06d2 \u0627\u0646\u0633\u0627\u0646 \u0648\u06c1\u06cc \u06c1\u06cc\u06ba \u062c\u0648 \u062f\u0648\u0633\u0631\u0648\u06ba \u06a9\u06d2 \u06a9\u0627\u0645 \u0622\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u067e\u0647 \u06cc\u0648\u0647 \u0648\u0646\u0647 \u06a9\u069a\u06d0 \u0646\u0627\u0633\u062a \u0628\u0644\u0628\u0644 \u0648\n\u0634\u067e\u0647 \u0631\u0627\u063a\u0644\u0647 \u0627\u0648 \u067e\u0647 \u0632\u0693\u0647 \u062e\u067e\u0647 \u0648\n\n\u0686\u06d0 \u0685\u0646\u06ab\u0647 \u0628\u0647 \u062e\u067e\u0644\u0648 \u0628\u0686\u0648 \u062a\u0647 \u0644\u0627\u0693 \u0634\u0645\n\u067e\u0647 \u062a\u06cc\u0627\u0631\u0647 \u06a9\u069a\u06d0 \u0681\u0627\u0644\u0647 \u0685\u0646\u06ab\u0647 \u0628\u06cc\u0627\u0645\u0648\u0645\u0645\u061f\n\n\u067e\u0647 \u062f\u06d0 \u0648\u062e\u062a \u06a9\u069a\u06d0 \u06cc\u0648 \u067e\u062a\u0646\u06ab \u0631\u0627\u063a\u06cc\n\u0647\u063a\u0647 \u0648\u0631\u062a\u0647 \u0648\u0648\u06cc\u0644: \u0627\u06cc \u0648\u0631\u0648\u0631\u0647!\n\n\u0632\u0647 \u0628\u0647 \u062e\u067e\u0644\u0647 \u0648\u0693\u0647 \u0631\u06bc\u0627 \u062f\u0631\u06a9\u0693\u0645\n\u0633\u062a\u0627 \u062f \u0644\u0627\u0631\u06d0 \u0645\u0634\u0627\u0644 \u0628\u0647 \u0634\u0645 \u0632\u0647\n\n\u062f\u06cc \u0647\u0645\u062f\u0631\u062f\u064a \u0686\u06d0 \u0685\u0648\u06a9 \u067e\u0647 \u06a9\u0627\u0631 \u0631\u0627\u0681\u064a\n\u062f \u0628\u0644 \u0686\u0627 \u067e\u0647 \u0633\u062e\u062a\u06cd \u0627\u0648 \u062a\u06cc\u0627\u0631\u0647 \u06a9\u069a\u06d0",
                "urdu": "\u0633\u0628\u0642 \"\u06c1\u0645\u062f\u0631\u062f\u06cc (\u0639\u0644\u0627\u0645\u06c1 \u0627\u0642\u0628\u0627\u0644 \u06a9\u06cc \u0646\u0638\u0645 \u06a9\u0627 \u067e\u0634\u062a\u0648 \u062a\u0631\u062c\u0645\u06c1)\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0639\u0644\u0627\u0645\u06c1 \u0627\u0642\u0628\u0627\u0644 \u06a9\u06cc \u0645\u0634\u06c1\u0648\u0631 \u0646\u0638\u0645 '\u06c1\u0645\u062f\u0631\u062f\u06cc' \u06a9\u0627 \u067e\u0634\u062a\u0648 \u0646\u062b\u0631\u06cc \u0648 \u0645\u0646\u0638\u0648\u0645 \u0645\u0641\u06c1\u0648\u0645\u06d4 \u0627\u06cc\u06a9 \u0646\u0646\u06be\u06d2 \u062c\u06af\u0646\u0648 \u0646\u06d2 \u0627\u0646\u062f\u06be\u06cc\u0631\u06cc \u0631\u0627\u062a \u0645\u06cc\u06ba \u067e\u0631\u06cc\u0634\u0627\u0646 \u0628\u0644\u0628\u0644 \u06a9\u0648 \u0627\u067e\u0646\u06cc \u0631\u0648\u0634\u0646\u06cc \u067e\u06cc\u0634 \u06a9\u06cc \u062a\u0627\u06a9\u06c1 \u0648\u06c1 \u0627\u067e\u0646\u06d2 \u06af\u06be\u0648\u0646\u0633\u0644\u06d2 \u062a\u06a9 \u067e\u06c1\u0646\u0686 \u0633\u06a9\u06d2\u06d4 \u0633\u0686\u06d2 \u0627\u0646\u0633\u0627\u0646 \u0648\u06c1\u06cc \u06c1\u06cc\u06ba \u062c\u0648 \u062f\u0648\u0633\u0631\u0648\u06ba \u06a9\u06d2 \u06a9\u0627\u0645 \u0622\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u062f\u0631\u0633 \u0645\u0647\u0645 \u067c\u06a9\u064a \u0648\u0644\u06cc\u06a9\u0626.",
                "pashtoAns": "\u067e\u0647 \u06cc\u0648\u0647 \u0648\u0646\u0647 \u06a9\u069a\u06d0 \u0646\u0627\u0633\u062a \u0628\u0644\u0628\u0644 \u0648\n\u0634\u067e\u0647 \u0631\u0627\u063a\u0644\u0647 \u0627\u0648 \u067e\u0647 \u0632\u0693\u0647 \u062e\u067e\u0647 \u0648\n\n\u0686\u06d0 \u0685\u0646\u06ab\u0647 \u0628\u0647 \u062e\u067e\u0644\u0648 \u0628\u0686\u0648 \u062a\u0647 \u0644\u0627\u0693 \u0634\u0645\n\u067e\u0647 \u062a\u06cc\u0627\u0631\u0647 \u06a9\u069a\u06d0 \u0681\u0627\u0644\u0647 \u0685\u0646\u06ab\u0647 \u0628\u06cc\u0627\u0645\u0648\u0645\u0645\u061f\n\n\u067e\u0647 \u062f\u06d0 \u0648\u062e\u062a \u06a9\u069a\u06d0 \u06cc\u0648 \u067e\u062a\u0646\u06ab \u0631\u0627\u063a\u06cc\n\u0647\u063a\u0647 \u0648\u0631\u062a\u0647 \u0648\u0648\u06cc\u0644: \u0627\u06cc \u0648\u0631\u0648\u0631\u0647!\n\n\u0632\u0647 \u0628\u0647 \u062e\u067e\u0644\u0647 \u0648\u0693\u0647 \u0631\u06bc\u0627 \u062f\u0631\u06a9\u0693\u0645\n\u0633\u062a\u0627 \u062f \u0644\u0627\u0631\u06d0 \u0645\u0634\u0627\u0644 \u0628\u0647 \u0634\u0645 \u0632\u0647\n\n\u062f\u06cc \u0647\u0645\u062f\u0631\u062f\u064a \u0686\u06d0 \u0685\u0648\u06a9 \u067e\u0647 \u06a9\u0627\u0631 \u0631\u0627\u0681\u064a\n\u062f \u0628\u0644 \u0686\u0627 \u067e\u0647 \u0633\u062e\u062a\u06cd \u0627\u0648 \u062a\u06cc\u0627\u0631\u0647 \u06a9\u069a\u06d0"
        }
]
