                "q": "\u062f \u062f\u06d0 \u0644\u0648\u0633\u062a \u0627\u062e\u0644\u0627\u0642\u064a \u0627\u0648 \u069a\u0648\u0648\u0646\u06cc\u0632 \u067e\u06cc\u063a\u0627\u0645 \u0685\u0647 \u062f\u06cc\u061f",
                "ans": "\u0639\u0644\u0627\u0645\u06c1 \u0627\u0642\u0628\u0627\u0644 \u06a9\u06cc \u0645\u0634\u06c1\u0648\u0631 \u0646\u0638\u0645 '\u06c1\u0645\u062f\u0631\u062f\u06cc' \u06a9\u0627 \u067e\u0634\u062a\u0648 \u0646\u062b\u0631\u06cc \u0648 \u0645\u0646\u0638\u0648\u0645 \u0645\u0641\u06c1\u0648\u0645\u06d4 \u0627\u06cc\u06a9 \u0646\u0646\u06be\u06d2 \u062c\u06af\u0646\u0648 \u0646\u06d2 \u0627\u0646\u062f\u06be\u06cc\u0631\u06cc \u0631\u0627\u062a \u0645\u06cc\u06ba \u067e\u0631\u06cc\u0634\u0627\u0646 \u0628\u0644\u0628\u0644 \u06a9\u0648 \u0627\u067e\u0646\u06cc \u0631\u0648\u0634\u0646\u06cc \u067e\u06cc\u0634 \u06a9\u06cc \u062a\u0627\u06a9\u06c1 \u0648\u06c1 \u0627\u067e\u0646\u06d2 \u06af\u06be\u0648\u0646\u0633\u0644\u06d2 \u062a\u06a9 \u067e\u06c1\u0646\u0686 \u0633\u06a9\u06d2\u06d4 \u0633\u0686\u06d2 \u0627\u0646\u0633\u0627\u0646 \u0648\u06c1\u06cc \u06c1\u06cc\u06ba \u062c\u0648 \u062f\u0648\u0633\u0631\u0648\u06ba \u06a9\u06d2 \u06a9\u0627\u0645 \u0622\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"
