                "ans": "\u0627\u0634\u0631 \u067e\u0647 \u06ab\u0689\u0647 \u062f \u06cc\u0648 \u0628\u0644 \u0633\u0631\u0647 \u062f \u06a9\u0627\u0631 \u0645\u0631\u0633\u062a\u06d0 \u062a\u0647 \u0648\u0627\u064a\u064a.",
                "urdu": "\u0627\u0634\u0631 \u06a9\u0633\u06d2 \u06a9\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u061f"
