      "lqs": [
        {
                "q": "\u062f \u062f\u06d0 \u0644\u0648\u0633\u062a \u0627\u062e\u0644\u0627\u0642\u064a \u0627\u0648 \u069a\u0648\u0648\u0646\u06cc\u0632 \u067e\u06cc\u063a\u0627\u0645 \u0685\u0647 \u062f\u06cc\u061f",
                "ans": "\u0627\u0634\u0631 \u067e\u062e\u062a\u0648\u0646\u0648\u06ba \u06a9\u0627 \u0642\u062f\u06cc\u0645 \u0631\u0648\u0627\u06cc\u062a\u06cc \u0646\u0638\u0627\u0645 \u06c1\u06d2 \u062c\u0633 \u0645\u06cc\u06ba \u06af\u0627\u0624\u06ba \u0648\u0627\u0644\u06d2 \u0628\u063a\u06cc\u0631 \u06a9\u0633\u06cc \u0627\u062c\u0631\u062a \u06a9\u06d2 \u0645\u0644 \u06a9\u0631 \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06d2 \u0641\u0635\u0644 \u06a9\u0627\u0679\u0646\u06d2\u060c \u0645\u06a9\u0627\u0646 \u0628\u0646\u0627\u0646\u06d2 \u0627\u0648\u0631 \u0646\u062f\u06cc \u0646\u0627\u0644\u0648\u06ba \u06a9\u06cc \u0635\u0641\u0627\u0626\u06cc \u0645\u06cc\u06ba \u06c1\u0627\u062a\u06be \u0628\u0679\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0627\u0633 \u0633\u06d2 \u0627\u062a\u062d\u0627\u062f \u0627\u0648\u0631 \u0628\u06be\u0627\u0626\u06cc \u0686\u0627\u0631\u06c1 \u0628\u0691\u06be\u062a\u0627 \u06c1\u06d2\u06d4"
        }
]
