      "shortQuestions": [
        {
                "id": "cls2-ps-ch11-sq1",
                "question": "\u0645\u0627\u0634\u0648\u0645 \u0685\u0647 \u0647\u0648\u0689 \u0644\u0631\u064a\u061f",
                "answer": "\u0645\u0627\u0634\u0648\u0645 \u0647\u0648\u0689 \u0644\u0631\u064a \u0686\u06d0 \u0644\u0633\u0645 \u067c\u0648\u0644\u06ab\u064a \u062a\u0647 \u0648\u0631\u0633\u06d0\u0696\u064a \u0627\u0648 \u062f \u0648\u0637\u0646 \u062e\u062f\u0645\u062a \u0648\u06a9\u0693\u064a.",
                "urdu": "\u0628\u0686\u06d2 \u06a9\u0627 \u06a9\u06cc\u0627 \u0627\u0631\u0627\u062f\u06c1 \u06c1\u06d2\u061f",
                "pashto": "\u0645\u0627\u0634\u0648\u0645 \u0685\u0647 \u0647\u0648\u0689 \u0644\u0631\u064a\u061f",
                "pashtoAns": "\u0686\u06d0 \u0689\u06d0\u0631 \u062f\u0631\u0633 \u0648\u0648\u0627\u06cc\u064a \u0627\u0648 \u0644\u0648\u06cc \u0634\u064a."
        },
        {
                "id": "cls2-ps-ch11-sq2",
                "question": "\u062f \u0645\u0627\u0634\u0648\u0645 \u0645\u0644\u06ab\u0631\u064a \u0685\u0647 \u062f\u064a\u061f",
                "answer": "\u06a9\u062a\u0627\u0628 \u0627\u0648 \u0642\u0644\u0645 \u062f \u0645\u0627\u0634\u0648\u0645 \u063a\u0648\u0631\u0647 \u0645\u0644\u06ab\u0631\u064a \u062f\u064a.",
                "urdu": "\u0628\u0686\u06d2 \u06a9\u06d2 \u0633\u0627\u062a\u06be\u06cc \u06a9\u0648\u0646 \u06c1\u06cc\u06ba\u061f",
                "pashto": "\u062f \u0645\u0627\u0634\u0648\u0645 \u0645\u0644\u06ab\u0631\u064a \u0685\u0647 \u062f\u064a\u061f",
                "pashtoAns": "\u06a9\u062a\u0627\u0628 \u0627\u0648 \u0642\u0644\u0645 \u06cc\u06d0 \u0645\u0644\u06ab\u0631\u064a \u062f\u064a."
        }
],
      "longQuestions": [
        {
                "id": "cls2-ps-ch11-lq1",
                "question": "\u062f \u0644\u0648\u0633\u062a \"\u0632\u0647 \u0628\u0647 \u0647\u0645 \u0644\u0633\u0645 \u062a\u0647 \u0634\u0645 (\u0646\u0638\u0645)\" \u0644\u0646\u0689\u06cc\u0632 \u0627\u0648 \u0645\u0647\u0645 \u067c\u06a9\u064a \u067e\u0647 \u062e\u067e\u0644\u0648 \u067c\u06a9\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u06cc\u06a9\u0626.",
                "answer": "\u0627\u06cc\u06a9 \u067e\u0631\u0639\u0632\u0645 \u0628\u0686\u06d2 \u06a9\u0627 \u062a\u0631\u0627\u0646\u06c1 \u062c\u0648 \u0627\u0628\u06be\u06cc \u0686\u06be\u0648\u0679\u0627 \u06c1\u06d2 \u0644\u06cc\u06a9\u0646 \u0627\u0631\u0627\u062f\u06c1 \u067e\u06a9\u0627 \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2\u06d4 \u0648\u06c1 \u0645\u062d\u0646\u062a \u0633\u06d2 \u067e\u06c1\u0644\u06cc \u0627\u0648\u0631 \u062f\u0648\u0633\u0631\u06cc \u062c\u0645\u0627\u0639\u062a \u0633\u06d2 \u0622\u06af\u06d2 \u0628\u0691\u06be \u06a9\u0631 \u062f\u0633\u0648\u06cc\u06ba \u062a\u06a9 \u062c\u0627\u0626\u06d2 \u06af\u0627 \u0627\u0648\u0631 \u0628\u0691\u0627 \u06c1\u0648 \u06a9\u0631 \u0688\u0627\u06a9\u0679\u0631\u060c \u0627\u0646\u062c\u06cc\u0646\u0626\u0631 \u06cc\u0627 \u0627\u0633\u062a\u0627\u062f \u0628\u0646 \u06a9\u0631 \u0645\u0644\u06a9 \u0648 \u0642\u0648\u0645 \u06a9\u06cc \u062e\u062f\u0645\u062a \u06a9\u0631\u06d2 \u06af\u0627\u06d4 \u0648\u0693\u0648\u06a9\u06d0 \u06cc\u0645 \u062e\u0648 \u0647\u0648\u0689 \u0644\u0631\u0645\n\u0633\u0628\u0627 \u0628\u0647 \u0644\u0648\u06cc \u0627\u0646\u0633\u0627\u0646 \u0634\u0645\u0647\n\n\u0644\u0647 \u0644\u0648\u0645\u0693\u064a \u067c\u0648\u0644\u06ab\u064a \u0631\u0648\u0627\u0646 \u06cc\u0645\n\u0632\u0647 \u0628\u0647 \u0647\u0645 \u0644\u0633\u0645 \u062a\u0647 \u0634\u0645\u0647\n\n\u06a9\u062a\u0627\u0628 \u0642\u0644\u0645 \u0645\u06d0 \u0645\u0644\u06ab\u0631\u064a \u062f\u064a\n\u062f \u069a\u0648\u0648\u0646\u06a9\u064a \u062e\u0628\u0631\u0647 \u0627\u0648\u0631\u0645\u0647\n\n\u0689\u0627\u06a9\u067c\u0631\u060c \u0627\u0646\u062c\u0646\u06cc\u0631 \u06cc\u0627 \u0627\u0633\u062a\u0627\u062f \u0628\u0647 \u0634\u0645\n\u062f \u062e\u067e\u0644 \u0648\u0637\u0646 \u062e\u062f\u0645\u062a \u06a9\u0648\u0645\u0647",
                "urdu": "\u0633\u0628\u0642 \"\u0645\u06cc\u06ba \u0628\u06be\u06cc \u062f\u0633\u0648\u06cc\u06ba \u062c\u0645\u0627\u0639\u062a \u0645\u06cc\u06ba \u062c\u0627\u0624\u06ba \u06af\u0627 (\u0646\u0638\u0645)\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0627\u06cc\u06a9 \u067e\u0631\u0639\u0632\u0645 \u0628\u0686\u06d2 \u06a9\u0627 \u062a\u0631\u0627\u0646\u06c1 \u062c\u0648 \u0627\u0628\u06be\u06cc \u0686\u06be\u0648\u0679\u0627 \u06c1\u06d2 \u0644\u06cc\u06a9\u0646 \u0627\u0631\u0627\u062f\u06c1 \u067e\u06a9\u0627 \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2\u06d4 \u0648\u06c1 \u0645\u062d\u0646\u062a \u0633\u06d2 \u067e\u06c1\u0644\u06cc \u0627\u0648\u0631 \u062f\u0648\u0633\u0631\u06cc \u062c\u0645\u0627\u0639\u062a \u0633\u06d2 \u0622\u06af\u06d2 \u0628\u0691\u06be \u06a9\u0631 \u062f\u0633\u0648\u06cc\u06ba \u062a\u06a9 \u062c\u0627\u0626\u06d2 \u06af\u0627 \u0627\u0648\u0631 \u0628\u0691\u0627 \u06c1\u0648 \u06a9\u0631 \u0688\u0627\u06a9\u0679\u0631\u060c \u0627\u0646\u062c\u06cc\u0646\u0626\u0631 \u06cc\u0627 \u0627\u0633\u062a\u0627\u062f \u0628\u0646 \u06a9\u0631 \u0645\u0644\u06a9 \u0648 \u0642\u0648\u0645 \u06a9\u06cc \u062e\u062f\u0645\u062a \u06a9\u0631\u06d2 \u06af\u0627\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u062f\u0631\u0633 \u0645\u0647\u0645 \u067c\u06a9\u064a \u0648\u0644\u06cc\u06a9\u0626.",
                "pashtoAns": "\u0648\u0693\u0648\u06a9\u06d0 \u06cc\u0645 \u062e\u0648 \u0647\u0648\u0689 \u0644\u0631\u0645\n\u0633\u0628\u0627 \u0628\u0647 \u0644\u0648\u06cc \u0627\u0646\u0633\u0627\u0646 \u0634\u0645\u0647\n\n\u0644\u0647 \u0644\u0648\u0645\u0693\u064a \u067c\u0648\u0644\u06ab\u064a \u0631\u0648\u0627\u0646 \u06cc\u0645\n\u0632\u0647 \u0628\u0647 \u0647\u0645 \u0644\u0633\u0645 \u062a\u0647 \u0634\u0645\u0647\n\n\u06a9\u062a\u0627\u0628 \u0642\u0644\u0645 \u0645\u06d0 \u0645\u0644\u06ab\u0631\u064a \u062f\u064a\n\u062f \u069a\u0648\u0648\u0646\u06a9\u064a \u062e\u0628\u0631\u0647 \u0627\u0648\u0631\u0645\u0647\n\n\u0689\u0627\u06a9\u067c\u0631\u060c \u0627\u0646\u062c\u0646\u06cc\u0631 \u06cc\u0627 \u0627\u0633\u062a\u0627\u062f \u0628\u0647 \u0634\u0645\n\u062f \u062e\u067e\u0644 \u0648\u0637\u0646 \u062e\u062f\u0645\u062a \u06a9\u0648\u0645\u0647"
        }
]
