                "ans": "\u06a9\u06be\u0627\u0646\u0627 \u06a9\u06be\u0627\u0646\u06d2 \u0633\u06d2 \u067e\u06c1\u0644\u06d2 \u06c1\u0627\u062a\u06be \u062f\u06be\u0648\u0646\u0627\u060c \u062f\u0627\u0626\u06cc\u06ba \u06c1\u0627\u062a\u06be \u0633\u06d2 \u0628\u0633\u0645 \u0627\u0644\u0644\u06c1 \u067e\u0691\u06be \u06a9\u0631 \u06a9\u06be\u0627\u0646\u0627\u060c \u0627\u067e\u0646\u06d2 \u0633\u0627\u0645\u0646\u06d2 \u0633\u06d2 \u06a9\u06be\u0627\u0646\u0627\u060c \u0627\u0648\u0631 \u067e\u0627\u0646\u06cc \u0628\u06cc\u0679\u06be \u06a9\u0631 \u062a\u06cc\u0646 \u0633\u0627\u0646\u0633\u0648\u06ba \u0645\u06cc\u06ba \u067e\u06cc\u0646\u0627 \u0633\u0646\u062a\u0650 \u0646\u0628\u0648\u06cc \u06c1\u06d2\u06d4 \u06a9\u06be\u0627\u0646\u06d2 \u06a9\u06d2 \u0628\u0639\u062f \u0627\u0644\u0644\u06c1 \u06a9\u0627 \u0634\u06a9\u0631 \u0627\u062f\u0627 \u06a9\u0631\u0646\u0627 \u0686\u0627\u06c1\u06cc\u06d2\u06d4"
