                "ans": "\u0633\u0631\u062f\u06cc\u0648\u06ba \u06a9\u06d2 \u0645\u0648\u0633\u0645 \u0645\u06cc\u06ba \u067e\u06c1\u0627\u0691\u0648\u06ba \u067e\u0631 \u0628\u0631\u0641 \u0628\u0627\u0631\u06cc \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u060c \u0679\u06be\u0646\u0688\u06cc \u06c1\u0648\u0627\u0626\u06cc\u06ba \u0686\u0644\u062a\u06cc \u06c1\u06cc\u06ba\u060c \u0644\u0648\u06af \u06af\u0631\u0645 \u0644\u0628\u0627\u0633 \u067e\u06c1\u0646\u062a\u06d2 \u06c1\u06cc\u06ba\u060c \u0622\u06af \u062a\u0627\u067e\u062a\u06d2 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u0686\u0627\u0626\u06d2 \u0648 \u062e\u0634\u06a9 \u0645\u06cc\u0648\u06c1 \u062c\u0627\u062a \u0633\u06d2 \u0644\u0637\u0641 \u0627\u0646\u062f\u0648\u0632 \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"
