      "longQuestions": [
        {
                "id": "cls2-ps-ch16-lq1",
                "question": "\u062f \u0644\u0648\u0633\u062a \"\u0632\u0645\u0648\u0646\u0696 \u0627\u062f\u0627\u0631\u06d0\" \u0644\u0646\u0689\u06cc\u0632 \u0627\u0648 \u0645\u0647\u0645 \u067c\u06a9\u064a \u067e\u0647 \u062e\u067e\u0644\u0648 \u067c\u06a9\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u06cc\u06a9\u0626.",
                "answer": "\u0633\u06a9\u0648\u0644\u060c \u06c1\u0633\u067e\u062a\u0627\u0644\u060c \u067e\u0648\u0644\u06cc\u0633 \u0627\u0633\u0679\u06cc\u0634\u0646\u060c \u0688\u0627\u06a9 \u062e\u0627\u0646\u06c1 \u0627\u0648\u0631 \u0639\u062f\u0627\u0644\u062a\u06cc\u06ba \u06c1\u0645\u0627\u0631\u06d2 \u0627\u06c1\u0645 \u0642\u0648\u0645\u06cc \u0627\u062f\u0627\u0631\u06d2 \u06c1\u06cc\u06ba \u062c\u0648 \u0634\u06c1\u0631\u06cc\u0648\u06ba \u06a9\u0648 \u062a\u0639\u0644\u06cc\u0645\u060c \u0635\u062d\u062a\u060c \u062a\u062d\u0641\u0638 \u0627\u0648\u0631 \u0627\u0646\u0635\u0627\u0641 \u0641\u0631\u0627\u06c1\u0645 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0627\u0646 \u06a9\u0627 \u0627\u062d\u062a\u0631\u0627\u0645 \u06c1\u0645 \u067e\u0631 \u0644\u0627\u0632\u0645 \u06c1\u06d2\u06d4 \u067e\u0647 \u06cc\u0648\u0647 \u0647\u06d0\u0648\u0627\u062f \u06a9\u069a\u06d0 \u062f \u062e\u0644\u06a9\u0648 \u062f \u062e\u062f\u0645\u062a \u0644\u067e\u0627\u0631\u0647 \u0628\u06d0\u0644\u0627\u0628\u06d0\u0644\u06d0 \u062d\u06a9\u0648\u0645\u062a\u064a \u0627\u062f\u0627\u0631\u06d0 \u06a9\u0627\u0631 \u06a9\u0648\u064a:\n\n\u06f1. \u069a\u0648\u0648\u0646\u0681\u06cc \u0627\u0648 \u067e\u0648\u0647\u0646\u062a\u0648\u0646: \u062f \u0639\u0644\u0645 \u0627\u0648 \u067e\u0648\u0647\u06d0 \u0645\u0631\u06a9\u0632\u0648\u0646\u0647 \u062f\u064a.\n\u06f2. \u0631\u0648\u063a\u062a\u0648\u0646: \u062f \u0646\u0627\u0631\u0648\u063a\u0627\u0646\u0648 \u062f\u0631\u0645\u0644\u0646\u0647 \u06a9\u0648\u064a.\n\u06f3. \u062a\u0627\u06bc\u0647 \u0627\u0648 \u067e\u0648\u0644\u06cc\u0633: \u062f \u062e\u0644\u06a9\u0648 \u062f \u0633\u0631 \u0627\u0648 \u0645\u0627\u0644 \u0633\u0627\u062a\u0646\u0647 \u06a9\u0648\u064a \u0627\u0648 \u0642\u0627\u0646\u0648\u0646 \u067e\u0644\u064a \u06a9\u0648\u064a.\n\u06f4. \u0689\u0627\u06a9\u062e\u0627\u0646\u0647: \u062e\u0637\u0648\u0646\u0647 \u0627\u0648 \u067e\u0627\u0631\u0633\u0644\u0648\u0646\u0647 \u0631\u0633\u0648\u064a.\n\u06f5. \u0639\u062f\u0627\u0644\u062a: \u062e\u0644\u06a9\u0648 \u062a\u0647 \u0627\u0646\u0635\u0627\u0641 \u0648\u0631\u06a9\u0648\u064a.\n\u062f\u0627 \u067c\u0648\u0644\u06d0 \u0632\u0645\u0648\u0696 \u0645\u0644\u064a \u0634\u062a\u0645\u0646\u06cd \u062f\u064a \u0627\u0648 \u0633\u0627\u062a\u0646\u0647 \u06cc\u06d0 \u0632\u0645\u0648\u0696 \u06ab\u0689\u0647 \u062f\u0646\u062f\u0647 \u062f\u0647.",
                "urdu": "\u0633\u0628\u0642 \"\u06c1\u0645\u0627\u0631\u06d2 \u0642\u0648\u0645\u06cc \u0627\u062f\u0627\u0631\u06d2\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0633\u06a9\u0648\u0644\u060c \u06c1\u0633\u067e\u062a\u0627\u0644\u060c \u067e\u0648\u0644\u06cc\u0633 \u0627\u0633\u0679\u06cc\u0634\u0646\u060c \u0688\u0627\u06a9 \u062e\u0627\u0646\u06c1 \u0627\u0648\u0631 \u0639\u062f\u0627\u0644\u062a\u06cc\u06ba \u06c1\u0645\u0627\u0631\u06d2 \u0627\u06c1\u0645 \u0642\u0648\u0645\u06cc \u0627\u062f\u0627\u0631\u06d2 \u06c1\u06cc\u06ba \u062c\u0648 \u0634\u06c1\u0631\u06cc\u0648\u06ba \u06a9\u0648 \u062a\u0639\u0644\u06cc\u0645\u060c \u0635\u062d\u062a\u060c \u062a\u062d\u0641\u0638 \u0627\u0648\u0631 \u0627\u0646\u0635\u0627\u0641 \u0641\u0631\u0627\u06c1\u0645 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0627\u0646 \u06a9\u0627 \u0627\u062d\u062a\u0631\u0627\u0645 \u06c1\u0645 \u067e\u0631 \u0644\u0627\u0632\u0645 \u06c1\u06d2\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u062f\u0631\u0633 \u0645\u0647\u0645 \u067c\u06a9\u064a \u0648\u0644\u06cc\u06a9\u0626.",
                "pashtoAns": "\u067e\u0647 \u06cc\u0648\u0647 \u0647\u06d0\u0648\u0627\u062f \u06a9\u069a\u06d0 \u062f \u062e\u0644\u06a9\u0648 \u062f \u062e\u062f\u0645\u062a \u0644\u067e\u0627\u0631\u0647 \u0628\u06d0\u0644\u0627\u0628\u06d0\u0644\u06d0 \u062d\u06a9\u0648\u0645\u062a\u064a \u0627\u062f\u0627\u0631\u06d0 \u06a9\u0627\u0631 \u06a9\u0648\u064a:\n\n\u06f1. \u069a\u0648\u0648\u0646\u0681\u06cc \u0627\u0648 \u067e\u0648\u0647\u0646\u062a\u0648\u0646: \u062f \u0639\u0644\u0645 \u0627\u0648 \u067e\u0648\u0647\u06d0 \u0645\u0631\u06a9\u0632\u0648\u0646\u0647 \u062f\u064a.\n\u06f2. \u0631\u0648\u063a\u062a\u0648\u0646: \u062f \u0646\u0627\u0631\u0648\u063a\u0627\u0646\u0648 \u062f\u0631\u0645\u0644\u0646\u0647 \u06a9\u0648\u064a.\n\u06f3. \u062a\u0627\u06bc\u0647 \u0627\u0648 \u067e\u0648\u0644\u06cc\u0633: \u062f \u062e\u0644\u06a9\u0648 \u062f \u0633\u0631 \u0627\u0648 \u0645\u0627\u0644 \u0633\u0627\u062a\u0646\u0647 \u06a9\u0648\u064a \u0627\u0648 \u0642\u0627\u0646\u0648\u0646 \u067e\u0644\u064a \u06a9\u0648\u064a.\n\u06f4. \u0689\u0627\u06a9\u062e\u0627\u0646\u0647: \u062e\u0637\u0648\u0646\u0647 \u0627\u0648 \u067e\u0627\u0631\u0633\u0644\u0648\u0646\u0647 \u0631\u0633\u0648\u064a.\n\u06f5. \u0639\u062f\u0627\u0644\u062a: \u062e\u0644\u06a9\u0648 \u062a\u0647 \u0627\u0646\u0635\u0627\u0641 \u0648\u0631\u06a9\u0648\u064a.\n\u062f\u0627 \u067c\u0648\u0644\u06d0 \u0632\u0645\u0648\u0696 \u0645\u0644\u064a \u0634\u062a\u0645\u0646\u06cd \u062f\u064a \u0627\u0648 \u0633\u0627\u062a\u0646\u0647 \u06cc\u06d0 \u0632\u0645\u0648\u0696 \u06ab\u0689\u0647 \u062f\u0646\u062f\u0647 \u062f\u0647."
        }
]
