                "ans": "\u0627\u06cc\u06a9 \u0633\u0645\u062c\u06be\u062f\u0627\u0631 \u0628\u0686\u06c1 \u0627\u067e\u0646\u06d2 \u0628\u0633\u062a\u06c1\u060c \u06a9\u062a\u0627\u0628\u0648\u06ba\u060c \u0642\u0644\u0645 \u0627\u0648\u0631 \u062c\u0648\u062a\u0648\u06ba \u06a9\u0648 \u0633\u0646\u0628\u06be\u0627\u0644 \u06a9\u0631 \u0645\u0642\u0631\u0631\u06c1 \u062c\u06af\u06c1 \u067e\u0631 \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2\u06d4 \u0686\u06cc\u0632\u0648\u06ba \u06a9\u06cc \u062f\u06cc\u06a9\u06be \u0628\u06be\u0627\u0644 \u06a9\u0631\u0646\u06d2 \u0633\u06d2 \u0635\u0641\u0627\u0626\u06cc \u0631\u06c1\u062a\u06cc \u06c1\u06d2 \u0627\u0648\u0631 \u0646\u0642\u0635\u0627\u0646 \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u062a\u0627\u06d4"
