                "ans": "\u067e\u062e\u062a\u0648\u0646 \u062f\u06cc\u06c1\u0627\u062a \u0645\u06cc\u06ba \u0631\u0648\u0627\u06cc\u062a\u06cc \u06a9\u06be\u06cc\u0644 \u062c\u06cc\u0633\u06d2 \u0686\u06be\u067e\u0646 \u0686\u06be\u067e\u0627\u0626\u06cc (\u067e\u0679 \u067e\u0679\u0648\u0646\u06cc)\u060c \u0622\u0646\u06a9\u06be \u0645\u0686\u0648\u0644\u06cc \u0627\u0648\u0631 \u06af\u0644\u06cc \u0688\u0646\u0688\u0627 \u06a9\u06be\u06cc\u0644\u06d2 \u062c\u0627\u062a\u06d2 \u06c1\u06cc\u06ba \u062c\u0648 \u0628\u0686\u0648\u06ba \u06a9\u0648 \u062a\u0646\u062f\u0631\u0633\u062a\u060c \u062a\u0648\u0627\u0646\u0627 \u0627\u0648\u0631 \u0686\u0633\u062a \u0631\u06a9\u06be\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"
