                "pashto": "\u067e\u0644\u0627\u0631 \u0645\u0627\u0634\u0648\u0645\u0627\u0646\u0648 \u062a\u0647 \u062f \u0622\u0632\u0627\u062f\u06cd \u067e\u0647 \u0627\u0693\u0647 \u0685\u0647 \u0648\u0648\u06cc\u0644\u061f",
