                "urdu": "\u062f\u06be\u0648\u06a9\u06d2 \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u06a9\u06cc\u0627 \u0627\u0631\u0634\u0627\u062f \u06c1\u06d2\u061f",
