                "urdu": "\u0645\u0639\u0627\u0634\u0631\u062a\u06cc \u0632\u0646\u062f\u06af\u06cc \u06a9\u0627 \u062d\u0633\u0646 \u06a9\u06cc\u0627 \u06c1\u06d2\u061f",
                "pashto": "\u062f \u067c\u0648\u0644\u0646\u06cc\u0632 \u0698\u0648\u0646\u062f \u069a\u06a9\u0644\u0627 \u067e\u0647 \u0685\u0647 \u06a9\u069a\u06d0 \u062f\u0647\u061f"
