      "shortQuestions": [
        {
                "id": "cls2-ps-ch23-sq1",
                "question": "\u067e\u0647 \u063a\u0645 \u0627\u0648 \u0645\u0635\u06cc\u0628\u062a \u06a9\u069a\u06d0 \u0685\u0647 \u067e\u06a9\u0627\u0631 \u062f\u064a\u061f",
                "answer": "\u0644\u0647 \u063a\u0645\u0681\u067e\u0644\u0648 \u0633\u0631\u0647 \u0645\u0631\u0633\u062a\u0647 \u06a9\u0648\u0644 \u0627\u0648 \u062a\u0633\u0644\u064a \u0648\u0631\u06a9\u0648\u0644 \u067e\u06a9\u0627\u0631 \u062f\u064a.",
                "urdu": "\u0645\u0635\u06cc\u0628\u062a \u0645\u06cc\u06ba \u06a9\u06cc\u0627 \u06a9\u0631\u0646\u0627 \u0686\u0627\u06c1\u06cc\u06d2\u061f",
                "pashto": "\u067e\u0647 \u063a\u0645 \u0627\u0648 \u0645\u0635\u06cc\u0628\u062a \u06a9\u069a\u06d0 \u0685\u0647 \u067e\u06a9\u0627\u0631 \u062f\u064a\u061f",
                "pashtoAns": "\u0645\u0631\u0633\u062a\u0647 \u0627\u0648 \u062a\u0633\u0644\u064a \u0648\u0631\u06a9\u0648\u0644 \u067e\u06a9\u0627\u0631 \u062f\u064a."
        },
        {
                "id": "cls2-ps-ch23-sq2",
                "question": "\u062f \u067c\u0648\u0644\u0646\u06cc\u0632 \u0698\u0648\u0646\u062f \u069a\u06a9\u0644\u0627 \u067e\u0647 \u0685\u0647 \u06a9\u069a\u06d0 \u062f\u0647\u061f",
                "answer": "\u062f \u06cc\u0648 \u0628\u0644 \u067e\u0647 \u063a\u0645 \u0627\u0648 \u069a\u0627\u062f\u06cd \u06a9\u06d0 \u0634\u0631\u06cc\u06a9\u06d0\u062f\u0644 \u062f\u064a.",
                "urdu": "\u0645\u0639\u0627\u0634\u0631\u062a\u06cc \u0632\u0646\u062f\u06af\u06cc \u06a9\u0627 \u062d\u0633\u0646 \u06a9\u06cc\u0627 \u06c1\u06d2\u061f",
                "pashto": "\u062f \u067c\u0648\u0644\u0646\u06cc\u0632 \u0698\u0648\u0646\u062f \u069a\u06a9\u0644\u0627 \u067e\u0647 \u0685\u0647 \u06a9\u069a\u06d0 \u062f\u0647\u061f",
                "pashtoAns": "\u062f \u06cc\u0648 \u0628\u0644 \u0645\u0644\u0627\u062a\u0693 \u06a9\u0648\u0644 \u062f\u064a."
        }
],
      "longQuestions": [
        {
                "id": "cls2-ps-ch23-lq1",
                "question": "\u062f \u0644\u0648\u0633\u062a \"\u063a\u0645 \u069a\u0627\u062f\u064a\" \u0644\u0646\u0689\u06cc\u0632 \u0627\u0648 \u0645\u0647\u0645 \u067c\u06a9\u064a \u067e\u0647 \u062e\u067e\u0644\u0648 \u067c\u06a9\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u06cc\u06a9\u0626.",
                "answer": "\u0645\u0639\u0627\u0634\u0631\u062a\u06cc \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u06ba \u067e\u0691\u0648\u0633\u06cc\u0648\u06ba \u0627\u0648\u0631 \u0631\u0634\u062a\u06c1 \u062f\u0627\u0631\u0648\u06ba \u06a9\u06cc \u062e\u0648\u0634\u06cc \u0645\u06cc\u06ba \u0634\u0631\u06cc\u06a9 \u06c1\u0648\u0646\u0627 \u0627\u0648\u0631 \u063a\u0645 \u0645\u06cc\u06ba \u0627\u0646 \u06a9\u0627 \u0633\u06c1\u0627\u0631\u0627 \u0628\u0646\u0646\u0627 \u0644\u0627\u0632\u0645\u06cc \u06c1\u06d2\u06d4 \u06cc\u06c1\u06cc \u0628\u0627\u06c1\u0645\u06cc \u06c1\u0645\u062f\u0631\u062f\u06cc \u0627\u0648\u0631 \u0627\u062e\u0648\u062a \u06a9\u0627 \u062a\u0642\u0627\u0636\u0627 \u06c1\u06d2\u06d4 \u0627\u0646\u0633\u0627\u0646 \u06cc\u0648\u0627\u0681\u06d0 \u0698\u0648\u0646\u062f \u0646\u0634\u064a \u06a9\u0648\u0644\u06cc. \u067e\u0647 \u067c\u0648\u0644\u0646\u0647 \u06a9\u069a\u06d0 \u062f \u06cc\u0648 \u0628\u0644 \u067e\u0647 \u062e\u0648\u0634\u062d\u0627\u0644\u06cd \u06a9\u069a\u06d0 \u062e\u0648\u0634\u062d\u0627\u0644\u0647 \u06a9\u06d0\u062f\u0644 \u0627\u0648 \u067e\u0647 \u063a\u0645 \u06a9\u069a\u06d0 \u0628\u0631\u062e\u0647 \u0627\u062e\u06cc\u0633\u062a\u0644 \u062f \u0698\u0648\u0646\u062f \u0627\u0635\u0644 \u069a\u06a9\u0644\u0627 \u062f\u0647.\n\n\u06a9\u0644\u0647 \u0686\u06d0 \u067e\u0647 \u06a9\u0644\u064a \u06a9\u069a\u06d0 \u062f \u0686\u0627 \u0648\u0627\u062f\u0647 \u0648\u064a\u060c \u067c\u0648\u0644 \u06ab\u0627\u0648\u0646\u0689\u06cc\u0627\u0646 \u0627\u0648 \u062e\u067e\u0644\u0648\u0627\u0646 \u0648\u0631\u0633\u0631\u0647 \u0645\u0631\u0633\u062a\u0647 \u06a9\u0648\u064a \u0627\u0648 \u0645\u0628\u0627\u0631\u06a9\u064a \u0648\u0631\u062a\u0647 \u0648\u0627\u064a\u064a.\n\n\u0627\u0648 \u06a9\u0647 \u062e\u062f\u0627\u06cc \u0645\u0647 \u06a9\u0693\u0647 \u067e\u0647 \u0686\u0627 \u063a\u0645 \u06cc\u0627 \u0645\u0635\u06cc\u0628\u062a \u0631\u0627\u0634\u064a\u060c \u067c\u0648\u0644 \u062e\u0644\u06a9 \u062f \u0647\u063a\u0648\u06cc \u062a\u0633\u0644\u064a \u06a9\u0648\u064a\u060c \u062f \u0647\u063a\u0648\u06cc \u062e\u0648\u0627\u062e\u0648\u0696\u064a \u06a9\u0648\u064a \u0627\u0648 \u062f\u0639\u0627 \u0648\u0631\u062a\u0647 \u06a9\u0648\u064a. \u062f\u0627 \u062f \u0627\u0633\u0644\u0627\u0645 \u0627\u0648 \u067e\u069a\u062a\u0648\u0646\u0648\u0644\u06cd \u069a\u06a9\u0644\u06cc \u0642\u0627\u0646\u0648\u0646 \u062f\u06cc.",
                "urdu": "\u0633\u0628\u0642 \"\u063a\u0645 \u0627\u0648\u0631 \u062e\u0648\u0634\u06cc \u0645\u06cc\u06ba \u0634\u0631\u06a9\u062a\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0645\u0639\u0627\u0634\u0631\u062a\u06cc \u0632\u0646\u062f\u06af\u06cc \u0645\u06cc\u06ba \u067e\u0691\u0648\u0633\u06cc\u0648\u06ba \u0627\u0648\u0631 \u0631\u0634\u062a\u06c1 \u062f\u0627\u0631\u0648\u06ba \u06a9\u06cc \u062e\u0648\u0634\u06cc \u0645\u06cc\u06ba \u0634\u0631\u06cc\u06a9 \u06c1\u0648\u0646\u0627 \u0627\u0648\u0631 \u063a\u0645 \u0645\u06cc\u06ba \u0627\u0646 \u06a9\u0627 \u0633\u06c1\u0627\u0631\u0627 \u0628\u0646\u0646\u0627 \u0644\u0627\u0632\u0645\u06cc \u06c1\u06d2\u06d4 \u06cc\u06c1\u06cc \u0628\u0627\u06c1\u0645\u06cc \u06c1\u0645\u062f\u0631\u062f\u06cc \u0627\u0648\u0631 \u0627\u062e\u0648\u062a \u06a9\u0627 \u062a\u0642\u0627\u0636\u0627 \u06c1\u06d2\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u062f\u0631\u0633 \u0645\u0647\u0645 \u067c\u06a9\u064a \u0648\u0644\u06cc\u06a9\u0626.",
                "pashtoAns": "\u0627\u0646\u0633\u0627\u0646 \u06cc\u0648\u0627\u0681\u06d0 \u0698\u0648\u0646\u062f \u0646\u0634\u064a \u06a9\u0648\u0644\u06cc. \u067e\u0647 \u067c\u0648\u0644\u0646\u0647 \u06a9\u069a\u06d0 \u062f \u06cc\u0648 \u0628\u0644 \u067e\u0647 \u062e\u0648\u0634\u062d\u0627\u0644\u06cd \u06a9\u069a\u06d0 \u062e\u0648\u0634\u062d\u0627\u0644\u0647 \u06a9\u06d0\u062f\u0644 \u0627\u0648 \u067e\u0647 \u063a\u0645 \u06a9\u069a\u06d0 \u0628\u0631\u062e\u0647 \u0627\u062e\u06cc\u0633\u062a\u0644 \u062f \u0698\u0648\u0646\u062f \u0627\u0635\u0644 \u069a\u06a9\u0644\u0627 \u062f\u0647.\n\n\u06a9\u0644\u0647 \u0686\u06d0 \u067e\u0647 \u06a9\u0644\u064a \u06a9\u069a\u06d0 \u062f \u0686\u0627 \u0648\u0627\u062f\u0647 \u0648\u064a\u060c \u067c\u0648\u0644 \u06ab\u0627\u0648\u0646\u0689\u06cc\u0627\u0646 \u0627\u0648 \u062e\u067e\u0644\u0648\u0627\u0646 \u0648\u0631\u0633\u0631\u0647 \u0645\u0631\u0633\u062a\u0647 \u06a9\u0648\u064a \u0627\u0648 \u0645\u0628\u0627\u0631\u06a9\u064a \u0648\u0631\u062a\u0647 \u0648\u0627\u064a\u064a.\n\n\u0627\u0648 \u06a9\u0647 \u062e\u062f\u0627\u06cc \u0645\u0647 \u06a9\u0693\u0647 \u067e\u0647 \u0686\u0627 \u063a\u0645 \u06cc\u0627 \u0645\u0635\u06cc\u0628\u062a \u0631\u0627\u0634\u064a\u060c \u067c\u0648\u0644 \u062e\u0644\u06a9 \u062f \u0647\u063a\u0648\u06cc \u062a\u0633\u0644\u064a \u06a9\u0648\u064a\u060c \u062f \u0647\u063a\u0648\u06cc \u062e\u0648\u0627\u062e\u0648\u0696\u064a \u06a9\u0648\u064a \u0627\u0648 \u062f\u0639\u0627 \u0648\u0631\u062a\u0647 \u06a9\u0648\u064a. \u062f\u0627 \u062f \u0627\u0633\u0644\u0627\u0645 \u0627\u0648 \u067e\u069a\u062a\u0648\u0646\u0648\u0644\u06cd \u069a\u06a9\u0644\u06cc \u0642\u0627\u0646\u0648\u0646 \u062f\u06cc."
        }
]
