      "longQuestions": [
        {
                "id": "cls2-ps-ch24-lq1",
                "question": "\u062f \u0644\u0648\u0633\u062a \"\u062f\u0648\u0646\u06d0 \u0627\u0693\u0648\u0646\u0647 (\u062f \u0648\u0646\u0648 \u0627\u0631\u0632\u069a\u062a)\" \u0644\u0646\u0689\u06cc\u0632 \u0627\u0648 \u0645\u0647\u0645 \u067c\u06a9\u064a \u067e\u0647 \u062e\u067e\u0644\u0648 \u067c\u06a9\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u06cc\u06a9\u0626.",
                "answer": "\u062f\u0631\u062e\u062a \u0632\u0645\u06cc\u0646 \u06a9\u0627 \u062d\u0633\u0646 \u0627\u0648\u0631 \u0632\u0646\u062f\u06af\u06cc \u06a9\u06cc \u0639\u0644\u0627\u0645\u062a \u06c1\u06cc\u06ba\u06d4 \u0648\u06c1 \u0622\u06a9\u0633\u06cc\u062c\u0646\u060c \u067e\u06be\u0644\u060c \u0644\u06a9\u0691\u06cc \u0627\u0648\u0631 \u0679\u06be\u0646\u0688\u0627 \u0633\u0627\u06cc\u06c1 \u0641\u0631\u0627\u06c1\u0645 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u067e\u0631\u0646\u062f\u06d2 \u062f\u0631\u062e\u062a\u0648\u06ba \u067e\u0631 \u0628\u0633\u06cc\u0631\u0627 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u06c1\u0645\u06cc\u06ba \u0632\u06cc\u0627\u062f\u06c1 \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u062f\u0631\u062e\u062a \u0644\u06af\u0627\u0646\u06d2 \u0686\u0627\u06c1\u0626\u06cc\u06ba\u06d4 \u0648\u0646\u06d0 \u0632\u0645\u0648\u0696 \u062f \u0681\u0645\u06a9\u06d0 \u0632\u0631\u063a\u0648\u0646 \u0632\u0693\u0647 \u062f\u06cc. \u06a9\u0647 \u0648\u0646\u06d0 \u0646\u0647 \u0648\u064a\u060c \u0698\u0648\u0646\u062f \u0646\u0627\u0634\u0648\u0646\u06cc \u062f\u06cc.\n\n\u06f1. \u0648\u0646\u06d0 \u0645\u0648\u0696 \u062a\u0647 \u067e\u0627\u06a9\u0647 \u0647\u0648\u0627 \u0627\u0648 \u0627\u06a9\u0633\u06cc\u062c\u0646 \u0631\u0627\u06a9\u0648\u064a.\n\u06f2. \u0645\u0648\u0696 \u062a\u0647 \u062e\u0648\u0627\u0696\u0647 \u0645\u06d0\u0648\u06d0 \u0644\u06a9\u0647 \u0645\u06bc\u06d0\u060c \u0632\u0631\u062f\u0627\u0644\u0648 \u0627\u0648 \u0628\u0627\u062f\u0627\u0645 \u0631\u0627\u06a9\u0648\u064a.\n\u06f3. \u067e\u0647 \u06ab\u0631\u0645 \u0627\u0648\u0693\u064a \u06a9\u069a\u06d0 \u0645\u0633\u0627\u0641\u0631\u0648 \u062a\u0647 \u06cc\u062e \u0633\u06cc\u0648\u0631\u06cc \u062c\u0648\u0693\u0648\u064a.\n\u06f4. \u0645\u0631\u063a\u0627\u0646 \u067e\u0647 \u0648\u0646\u0648 \u06a9\u069a\u06d0 \u0681\u0627\u0644\u06d0 \u062c\u0648\u0693\u0648\u064a \u0627\u0648 \u0628\u0627\u0631\u0627\u0646\u0648\u0646\u0647 \u0631\u0627\u062c\u0644\u0628\u0648\u064a.\n\u0645\u0648\u0696 \u0628\u0627\u06cc\u062f \u0628\u06d0 \u0681\u0627\u06cc\u0647 \u0648\u0646\u06d0 \u0648\u0646\u0647 \u0648\u0647\u0648\u060c \u0628\u0644\u06a9\u06d0 \u0647\u0631 \u06a9\u0627\u0644 \u0646\u0648\u064a \u0646\u06cc\u0627\u0644\u06ab\u064a \u06a9\u06d0\u0646\u0648\u0648.",
                "urdu": "\u0633\u0628\u0642 \"\u062f\u0631\u062e\u062a\u0648\u06ba \u06a9\u06cc \u0627\u06c1\u0645\u06cc\u062a \u0627\u0648\u0631 \u0634\u062c\u0631\u06a9\u0627\u0631\u06cc\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u062f\u0631\u062e\u062a \u0632\u0645\u06cc\u0646 \u06a9\u0627 \u062d\u0633\u0646 \u0627\u0648\u0631 \u0632\u0646\u062f\u06af\u06cc \u06a9\u06cc \u0639\u0644\u0627\u0645\u062a \u06c1\u06cc\u06ba\u06d4 \u0648\u06c1 \u0622\u06a9\u0633\u06cc\u062c\u0646\u060c \u067e\u06be\u0644\u060c \u0644\u06a9\u0691\u06cc \u0627\u0648\u0631 \u0679\u06be\u0646\u0688\u0627 \u0633\u0627\u06cc\u06c1 \u0641\u0631\u0627\u06c1\u0645 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u067e\u0631\u0646\u062f\u06d2 \u062f\u0631\u062e\u062a\u0648\u06ba \u067e\u0631 \u0628\u0633\u06cc\u0631\u0627 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u06c1\u0645\u06cc\u06ba \u0632\u06cc\u0627\u062f\u06c1 \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u062f\u0631\u062e\u062a \u0644\u06af\u0627\u0646\u06d2 \u0686\u0627\u06c1\u0626\u06cc\u06ba\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u062f\u0631\u0633 \u0645\u0647\u0645 \u067c\u06a9\u064a \u0648\u0644\u06cc\u06a9\u0626.",
                "pashtoAns": "\u0648\u0646\u06d0 \u0632\u0645\u0648\u0696 \u062f \u0681\u0645\u06a9\u06d0 \u0632\u0631\u063a\u0648\u0646 \u0632\u0693\u0647 \u062f\u06cc. \u06a9\u0647 \u0648\u0646\u06d0 \u0646\u0647 \u0648\u064a\u060c \u0698\u0648\u0646\u062f \u0646\u0627\u0634\u0648\u0646\u06cc \u062f\u06cc.\n\n\u06f1. \u0648\u0646\u06d0 \u0645\u0648\u0696 \u062a\u0647 \u067e\u0627\u06a9\u0647 \u0647\u0648\u0627 \u0627\u0648 \u0627\u06a9\u0633\u06cc\u062c\u0646 \u0631\u0627\u06a9\u0648\u064a.\n\u06f2. \u0645\u0648\u0696 \u062a\u0647 \u062e\u0648\u0627\u0696\u0647 \u0645\u06d0\u0648\u06d0 \u0644\u06a9\u0647 \u0645\u06bc\u06d0\u060c \u0632\u0631\u062f\u0627\u0644\u0648 \u0627\u0648 \u0628\u0627\u062f\u0627\u0645 \u0631\u0627\u06a9\u0648\u064a.\n\u06f3. \u067e\u0647 \u06ab\u0631\u0645 \u0627\u0648\u0693\u064a \u06a9\u069a\u06d0 \u0645\u0633\u0627\u0641\u0631\u0648 \u062a\u0647 \u06cc\u062e \u0633\u06cc\u0648\u0631\u06cc \u062c\u0648\u0693\u0648\u064a.\n\u06f4. \u0645\u0631\u063a\u0627\u0646 \u067e\u0647 \u0648\u0646\u0648 \u06a9\u069a\u06d0 \u0681\u0627\u0644\u06d0 \u062c\u0648\u0693\u0648\u064a \u0627\u0648 \u0628\u0627\u0631\u0627\u0646\u0648\u0646\u0647 \u0631\u0627\u062c\u0644\u0628\u0648\u064a.\n\u0645\u0648\u0696 \u0628\u0627\u06cc\u062f \u0628\u06d0 \u0681\u0627\u06cc\u0647 \u0648\u0646\u06d0 \u0648\u0646\u0647 \u0648\u0647\u0648\u060c \u0628\u0644\u06a9\u06d0 \u0647\u0631 \u06a9\u0627\u0644 \u0646\u0648\u064a \u0646\u06cc\u0627\u0644\u06ab\u064a \u06a9\u06d0\u0646\u0648\u0648."
        }
]
