                "question": "\u062f \u06a9\u0645\u067e\u06cc\u0648\u067c\u0631 \u0645\u063a\u0632 \u06a9\u0648\u0645\u06d0 \u0628\u0631\u062e\u06d0 \u062a\u0647 \u0648\u0627\u064a\u064a\u061f",
                "answer": "\u0633\u064a \u067e\u064a \u06cc\u0648 (CPU) \u062a\u0647 \u062f \u06a9\u0645\u067e\u06cc\u0648\u067c\u0631 \u0645\u063a\u0632 \u0648\u0627\u064a\u064a.",
                "urdu": "\u06a9\u0645\u067e\u06cc\u0648\u0679\u0631 \u06a9\u0627 \u062f\u0645\u0627\u063a \u06a9\u0633\u06d2 \u06a9\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u061f",
