                "id": "cls2-ps-ch25-sq2",
                "question": "\u06a9\u06cc\u0628\u0648\u0631\u0689 \u062f \u0685\u0647 \u0644\u067e\u0627\u0631\u0647 \u06a9\u0627\u0631\u0648\u0644 \u06a9\u06cc\u0696\u064a\u061f",
                "answer": "\u06a9\u06cc\u0628\u0648\u0631\u0689 \u062f \u062a\u0648\u0631\u0648 \u0627\u0648 \u0639\u062f\u062f\u0648\u0646\u0648 \u062f \u0644\u06cc\u06a9\u0644\u0648 \u0644\u067e\u0627\u0631\u0647 \u06a9\u0627\u0631\u0648\u0644 \u06a9\u06cc\u0696\u064a.",
