      "longQuestions": [
        {
                "id": "cls2-ps-ch25-lq1",
                "question": "\u062f \u0644\u0648\u0633\u062a \"\u06a9\u0645\u067e\u06cc\u0648\u067c\u0631\" \u0644\u0646\u0689\u06cc\u0632 \u0627\u0648 \u0645\u0647\u0645 \u067c\u06a9\u064a \u067e\u0647 \u062e\u067e\u0644\u0648 \u067c\u06a9\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u06cc\u06a9\u0626.",
                "answer": "\u06a9\u0645\u067e\u06cc\u0648\u0679\u0631 \u062f\u0648\u0631\u0650 \u062c\u062f\u06cc\u062f \u06a9\u06cc \u062d\u06cc\u0631\u062a \u0627\u0646\u06af\u06cc\u0632 \u0627\u06cc\u062c\u0627\u062f \u06c1\u06d2\u06d4 \u0627\u0633 \u06a9\u06d2 \u0686\u0627\u0631 \u0627\u06c1\u0645 \u062d\u0635\u06d2 \u0645\u0627\u0646\u06cc\u0679\u0631\u060c \u06a9\u06cc \u0628\u0648\u0631\u0688\u060c \u0645\u0627\u0624\u0633 \u0627\u0648\u0631 \u0633\u06cc \u067e\u06cc \u06cc\u0648 \u06c1\u06cc\u06ba\u06d4 \u06cc\u06c1 \u062d\u0633\u0627\u0628 \u06a9\u062a\u0627\u0628\u060c \u067e\u0691\u06be\u0627\u0626\u06cc \u0627\u0648\u0631 \u067e\u06cc\u063a\u0627\u0645\u0627\u062a \u0628\u06be\u06cc\u062c\u0646\u06d2 \u0645\u06cc\u06ba \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4 \u06a9\u0645\u067e\u06cc\u0648\u067c\u0631 \u062f \u0627\u0648\u0633\u0646\u06cd \u0632\u0645\u0627\u0646\u06d0 \u06cc\u0648 \u0689\u06d0\u0631 \u06ab\u067c\u0648\u0631 \u0627\u0648 \u0686\u067c\u06a9 \u0628\u0631\u06d0\u069a\u0646\u0627\u064a\u064a \u0645\u0627\u0634\u06cc\u0646 \u062f\u06cc.\n\n\u062f \u06a9\u0645\u067e\u06cc\u0648\u067c\u0631 \u0627\u0635\u0644\u064a \u0628\u0631\u062e\u06d0 \u062f\u0627 \u062f\u064a:\n\u2022 \u0645\u0627\u0646\u06cc\u067c\u0631 (Monitor): \u067e\u0631\u062f\u0647 \u0686\u06d0 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0648 \u062a\u0635\u0648\u06cc\u0631\u0648\u0646\u0647 \u069a\u064a\u064a.\n\u2022 \u06a9\u06cc\u0628\u0648\u0631\u0689 (Keyboard): \u062f \u062a\u0648\u0631\u0648 \u0627\u0648 \u0634\u0645\u06d0\u0631\u0648 \u062f \u0644\u06cc\u06a9\u0644\u0648 \u062a\u062e\u062a\u0647.\n\u2022 \u0645\u0627\u0624\u0633 (Mouse): \u067e\u0647 \u0633\u06a9\u0631\u06cc\u0646 \u062f \u0627\u0634\u0627\u0631\u06d0 \u0627\u0648 \u06a9\u0645\u0627\u0646\u0689 \u0622\u0644\u0647.\n\u2022 \u0633\u064a \u067e\u064a \u06cc\u0648 (CPU): \u062f \u06a9\u0645\u067e\u06cc\u0648\u067c\u0631 \u0645\u063a\u0632 \u0686\u06d0 \u067c\u0648\u0644 \u062d\u0633\u0627\u0628\u0648\u0646\u0647 \u06a9\u0648\u064a.\n\n\u0645\u0648\u0696 \u067e\u0647 \u06a9\u0645\u067e\u06cc\u0648\u067c\u0631 \u06a9\u062a\u0627\u0628\u0648\u0646\u0647 \u0644\u0648\u0644\u0648\u060c \u062d\u0633\u0627\u0628 \u0632\u062f\u0647 \u06a9\u0648\u0648\u060c \u062e\u0637\u0648\u0646\u0647 \u0644\u06d0\u0696\u0648 \u0627\u0648 \u0646\u0648\u06d0 \u067e\u0648\u0647\u0647 \u062a\u0631\u0644\u0627\u0633\u0647 \u06a9\u0648\u0648.",
                "urdu": "\u0633\u0628\u0642 \"\u06a9\u0645\u067e\u06cc\u0648\u0679\u0631\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u06a9\u0645\u067e\u06cc\u0648\u0679\u0631 \u062f\u0648\u0631\u0650 \u062c\u062f\u06cc\u062f \u06a9\u06cc \u062d\u06cc\u0631\u062a \u0627\u0646\u06af\u06cc\u0632 \u0627\u06cc\u062c\u0627\u062f \u06c1\u06d2\u06d4 \u0627\u0633 \u06a9\u06d2 \u0686\u0627\u0631 \u0627\u06c1\u0645 \u062d\u0635\u06d2 \u0645\u0627\u0646\u06cc\u0679\u0631\u060c \u06a9\u06cc \u0628\u0648\u0631\u0688\u060c \u0645\u0627\u0624\u0633 \u0627\u0648\u0631 \u0633\u06cc \u067e\u06cc \u06cc\u0648 \u06c1\u06cc\u06ba\u06d4 \u06cc\u06c1 \u062d\u0633\u0627\u0628 \u06a9\u062a\u0627\u0628\u060c \u067e\u0691\u06be\u0627\u0626\u06cc \u0627\u0648\u0631 \u067e\u06cc\u063a\u0627\u0645\u0627\u062a \u0628\u06be\u06cc\u062c\u0646\u06d2 \u0645\u06cc\u06ba \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u062f\u0631\u0633 \u0645\u0647\u0645 \u067c\u06a9\u064a \u0648\u0644\u06cc\u06a9\u0626.",
                "pashtoAns": "\u06a9\u0645\u067e\u06cc\u0648\u067c\u0631 \u062f \u0627\u0648\u0633\u0646\u06cd \u0632\u0645\u0627\u0646\u06d0 \u06cc\u0648 \u0689\u06d0\u0631 \u06ab\u067c\u0648\u0631 \u0627\u0648 \u0686\u067c\u06a9 \u0628\u0631\u06d0\u069a\u0646\u0627\u064a\u064a \u0645\u0627\u0634\u06cc\u0646 \u062f\u06cc.\n\n\u062f \u06a9\u0645\u067e\u06cc\u0648\u067c\u0631 \u0627\u0635\u0644\u064a \u0628\u0631\u062e\u06d0 \u062f\u0627 \u062f\u064a:\n\u2022 \u0645\u0627\u0646\u06cc\u067c\u0631 (Monitor): \u067e\u0631\u062f\u0647 \u0686\u06d0 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0648 \u062a\u0635\u0648\u06cc\u0631\u0648\u0646\u0647 \u069a\u064a\u064a.\n\u2022 \u06a9\u06cc\u0628\u0648\u0631\u0689 (Keyboard): \u062f \u062a\u0648\u0631\u0648 \u0627\u0648 \u0634\u0645\u06d0\u0631\u0648 \u062f \u0644\u06cc\u06a9\u0644\u0648 \u062a\u062e\u062a\u0647.\n\u2022 \u0645\u0627\u0624\u0633 (Mouse): \u067e\u0647 \u0633\u06a9\u0631\u06cc\u0646 \u062f \u0627\u0634\u0627\u0631\u06d0 \u0627\u0648 \u06a9\u0645\u0627\u0646\u0689 \u0622\u0644\u0647.\n\u2022 \u0633\u064a \u067e\u064a \u06cc\u0648 (CPU): \u062f \u06a9\u0645\u067e\u06cc\u0648\u067c\u0631 \u0645\u063a\u0632 \u0686\u06d0 \u067c\u0648\u0644 \u062d\u0633\u0627\u0628\u0648\u0646\u0647 \u06a9\u0648\u064a.\n\n\u0645\u0648\u0696 \u067e\u0647 \u06a9\u0645\u067e\u06cc\u0648\u067c\u0631 \u06a9\u062a\u0627\u0628\u0648\u0646\u0647 \u0644\u0648\u0644\u0648\u060c \u062d\u0633\u0627\u0628 \u0632\u062f\u0647 \u06a9\u0648\u0648\u060c \u062e\u0637\u0648\u0646\u0647 \u0644\u06d0\u0696\u0648 \u0627\u0648 \u0646\u0648\u06d0 \u067e\u0648\u0647\u0647 \u062a\u0631\u0644\u0627\u0633\u0647 \u06a9\u0648\u0648."
        }
]
