                "pashto": "\u067e\u0647 \u062e\u06cc\u0628\u0631 \u067e\u062e\u062a\u0648\u0646\u062e\u0648\u0627 \u06a9\u069a\u06d0 \u06a9\u0648\u0645 \u062e\u0648\u0627\u0693\u0647 \u0689\u06d0\u0631 \u0645\u0634\u0647\u0648\u0631 \u062f\u064a\u061f",
