                "question": "\u062f \u0628\u0644\u0648\u0686\u0633\u062a\u0627\u0646 \u0645\u0634\u0647\u0648\u0631 \u062e\u0648\u0631\u0627\u06a9 \u06a9\u0648\u0645 \u062f\u06cc\u061f",
