                "pashto": "\u067e\u0647 \u062f\u0639\u0627 \u06a9\u069a\u06d0 \u0644\u0647 \u0627\u0644\u0644\u0647 \u0646\u0647 \u0685\u0647 \u063a\u0648\u069a\u062a\u0644 \u0634\u0648\u064a \u062f\u064a\u061f"
