      "longQuestions": [
        {
                "id": "cls2-ps-ch27-lq1",
                "question": "\u062f \u0644\u0648\u0633\u062a \"\u062f\u0639\u0627 (\u0646\u0638\u0645)\" \u0644\u0646\u0689\u06cc\u0632 \u0627\u0648 \u0645\u0647\u0645 \u067c\u06a9\u064a \u067e\u0647 \u062e\u067e\u0644\u0648 \u067c\u06a9\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u06cc\u06a9\u0626.",
                "answer": "\u0627\u06d2 \u062a\u0645\u0627\u0645 \u062c\u06c1\u0627\u0646\u0648\u06ba \u06a9\u06d2 \u067e\u0627\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0627\u0644\u0644\u06c1! \u06c1\u0645\u06cc\u06ba \u0646\u06cc\u06a9\u06cc \u06a9\u0627 \u0631\u0627\u0633\u062a\u06c1 \u062f\u06a9\u06be\u0627 \u0627\u0648\u0631 \u0628\u0631\u0627\u0626\u06cc \u0633\u06d2 \u0628\u0686\u0627\u06d4 \u06c1\u0645\u06cc\u06ba \u0639\u0644\u0645\u060c \u0639\u0642\u0644 \u0627\u0648\u0631 \u0648\u0637\u0646 \u06a9\u06cc \u0645\u062d\u0628\u062a \u0639\u0637\u0627 \u0641\u0631\u0645\u0627\u06d4 \u06c1\u0645\u0627\u0631\u06d2 \u0648\u0627\u0644\u062f\u06cc\u0646 \u06a9\u0648 \u062e\u0648\u0634 \u0631\u06a9\u06be \u0627\u0648\u0631 \u06c1\u0645\u0627\u0631\u06d2 \u0633\u06a9\u0648\u0644 \u06a9\u0648 \u0622\u0628\u0627\u062f \u0631\u06a9\u06be\u06d4 \u0627\u06cc \u0632\u0645\u0627 \u0644\u0648\u06cc\u0647 \u067e\u0631\u0648\u0631\u062f\u06ab\u0627\u0631\u0647\n\u0627\u06cc \u062f \u067c\u0648\u0644 \u062c\u0647\u0627\u0646 \u0628\u0627\u062f\u0627\u0631\u0647\n\n\u0645\u0648\u0696 \u062a\u0647 \u0646\u06d0\u06a9\u0647 \u0644\u0627\u0631 \u0648\u069a\u0627\u06cc\u0647\n\u062f \u0628\u062f\u0648 \u06a9\u0627\u0631\u0648 \u0646\u0647 \u0645\u0648 \u0648\u0633\u0627\u062a\u0647\n\n\u0639\u0644\u0645 \u0627\u0648 \u067e\u0648\u0647\u0647 \u0631\u0627\u06a9\u0693\u0647 \u062e\u062f\u0627\u06cc\u0647\n\u062f \u0648\u0637\u0646 \u0645\u06cc\u0646\u0647 \u0631\u0627\u06a9\u0693\u0647 \u062e\u062f\u0627\u06cc\u0647\n\n\u0645\u0648\u0631 \u0627\u0648 \u067e\u0644\u0627\u0631 \u0645\u0648 \u062e\u0648\u0634\u062d\u0627\u0644\u0647 \u0644\u0631\u0647\n\u0632\u0645\u0648\u0696 \u069a\u0648\u0648\u0646\u0681\u06cc \u0627\u0628\u0627\u062f \u0644\u0631\u0647",
                "urdu": "\u0633\u0628\u0642 \"\u062f\u0639\u0627 (\u0646\u0638\u0645)\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0627\u06d2 \u062a\u0645\u0627\u0645 \u062c\u06c1\u0627\u0646\u0648\u06ba \u06a9\u06d2 \u067e\u0627\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0627\u0644\u0644\u06c1! \u06c1\u0645\u06cc\u06ba \u0646\u06cc\u06a9\u06cc \u06a9\u0627 \u0631\u0627\u0633\u062a\u06c1 \u062f\u06a9\u06be\u0627 \u0627\u0648\u0631 \u0628\u0631\u0627\u0626\u06cc \u0633\u06d2 \u0628\u0686\u0627\u06d4 \u06c1\u0645\u06cc\u06ba \u0639\u0644\u0645\u060c \u0639\u0642\u0644 \u0627\u0648\u0631 \u0648\u0637\u0646 \u06a9\u06cc \u0645\u062d\u0628\u062a \u0639\u0637\u0627 \u0641\u0631\u0645\u0627\u06d4 \u06c1\u0645\u0627\u0631\u06d2 \u0648\u0627\u0644\u062f\u06cc\u0646 \u06a9\u0648 \u062e\u0648\u0634 \u0631\u06a9\u06be \u0627\u0648\u0631 \u06c1\u0645\u0627\u0631\u06d2 \u0633\u06a9\u0648\u0644 \u06a9\u0648 \u0622\u0628\u0627\u062f \u0631\u06a9\u06be\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u062f\u0631\u0633 \u0645\u0647\u0645 \u067c\u06a9\u064a \u0648\u0644\u06cc\u06a9\u0626.",
                "pashtoAns": "\u0627\u06cc \u0632\u0645\u0627 \u0644\u0648\u06cc\u0647 \u067e\u0631\u0648\u0631\u062f\u06ab\u0627\u0631\u0647\n\u0627\u06cc \u062f \u067c\u0648\u0644 \u062c\u0647\u0627\u0646 \u0628\u0627\u062f\u0627\u0631\u0647\n\n\u0645\u0648\u0696 \u062a\u0647 \u0646\u06d0\u06a9\u0647 \u0644\u0627\u0631 \u0648\u069a\u0627\u06cc\u0647\n\u062f \u0628\u062f\u0648 \u06a9\u0627\u0631\u0648 \u0646\u0647 \u0645\u0648 \u0648\u0633\u0627\u062a\u0647\n\n\u0639\u0644\u0645 \u0627\u0648 \u067e\u0648\u0647\u0647 \u0631\u0627\u06a9\u0693\u0647 \u062e\u062f\u0627\u06cc\u0647\n\u062f \u0648\u0637\u0646 \u0645\u06cc\u0646\u0647 \u0631\u0627\u06a9\u0693\u0647 \u062e\u062f\u0627\u06cc\u0647\n\n\u0645\u0648\u0631 \u0627\u0648 \u067e\u0644\u0627\u0631 \u0645\u0648 \u062e\u0648\u0634\u062d\u0627\u0644\u0647 \u0644\u0631\u0647\n\u0632\u0645\u0648\u0696 \u069a\u0648\u0648\u0646\u0681\u06cc \u0627\u0628\u0627\u062f \u0644\u0631\u0647"
        }
]
