      "shortQuestions": [
        {
                "id": "cls2-ps-ch28-sq1",
                "question": "\u062f \u067e\u069a\u062a\u0646\u064a \u06a9\u0644\u062a\u0648\u0631 \u0645\u0647\u0645\u06d0 \u0681\u0627\u0646\u06ab\u0693\u0646\u06d0 \u0685\u0647 \u062f\u064a\u061f",
                "answer": "\u0645\u06d0\u0644\u0645\u0647 \u067e\u0627\u0644\u0646\u0647\u060c \u0646\u0646\u06ab\u060c \u0648\u0639\u062f\u0647 \u067e\u0648\u0631\u0647 \u06a9\u0648\u0644 \u0627\u0648 \u062f \u062d\u062c\u0631\u0648 \u062f\u0648\u062f\u0648\u0646\u0647 \u062f\u064a.",
                "urdu": "\u067e\u062e\u062a\u0648\u0646 \u062b\u0642\u0627\u0641\u062a \u06a9\u06cc \u06a9\u06cc\u0627 \u062e\u0635\u0648\u0635\u06cc\u0627\u062a \u06c1\u06cc\u06ba\u061f",
                "pashto": "\u062f \u067e\u069a\u062a\u0646\u064a \u06a9\u0644\u062a\u0648\u0631 \u0645\u0647\u0645\u06d0 \u0681\u0627\u0646\u06ab\u0693\u0646\u06d0 \u0685\u0647 \u062f\u064a\u061f",
                "pashtoAns": "\u0645\u06d0\u0644\u0645\u0647 \u067e\u0627\u0644\u0646\u0647 \u0627\u0648 \u063a\u06cc\u0631\u062a."
        },
        {
                "id": "cls2-ps-ch28-sq2",
                "question": "\u062f \u067e\u069a\u062a\u0648 \u0698\u0628\u06d0 \u0645\u0634\u0647\u0648\u0631 \u0644\u0648\u06a9 \u0634\u0639\u0631\u0648\u0646\u0647 \u06a9\u0648\u0645 \u062f\u064a\u061f",
                "answer": "\u067c\u067e\u06d0\u060c \u0644\u0646\u0689\u06cd \u0627\u0648 \u0686\u0627\u0631\u0628\u06d0\u062a\u06d0 \u062f\u064a.",
                "urdu": "\u067e\u0634\u062a\u0648 \u0644\u0648\u06a9 \u0634\u0627\u0639\u0631\u06cc \u06a9\u06cc\u0627 \u06c1\u06d2\u061f",
                "pashto": "\u062f \u067e\u069a\u062a\u0648 \u0698\u0628\u06d0 \u0645\u0634\u0647\u0648\u0631 \u0644\u0648\u06a9 \u0634\u0639\u0631\u0648\u0646\u0647 \u06a9\u0648\u0645 \u062f\u064a\u061f",
                "pashtoAns": "\u067c\u067e\u06d0 \u0627\u0648 \u0644\u0646\u0689\u06cd \u062f\u064a."
        }
],
      "longQuestions": [
        {
                "id": "cls2-ps-ch28-lq1",
                "question": "\u062f \u0644\u0648\u0633\u062a \"\u0641\u0631\u0647\u0646\u06ab (\u0632\u0645\u0648\u0646\u0696 \u06a9\u0644\u062a\u0648\u0631 \u0627\u0648 \u0698\u0628\u0647)\" \u0644\u0646\u0689\u06cc\u0632 \u0627\u0648 \u0645\u0647\u0645 \u067c\u06a9\u064a \u067e\u0647 \u062e\u067e\u0644\u0648 \u067c\u06a9\u0648 \u06a9\u069a\u06d0 \u0648\u0644\u06cc\u06a9\u0626.",
                "answer": "\u067e\u0634\u062a\u0648 \u0627\u06cc\u06a9 \u0642\u062f\u06cc\u0645\u060c \u0634\u06cc\u0631\u06cc\u06ba \u0627\u0648\u0631 \u062a\u0627\u0631\u06cc\u062e\u06cc \u0632\u0628\u0627\u0646 \u06c1\u06d2\u06d4 \u067e\u062e\u062a\u0648\u0646 \u062b\u0642\u0627\u0641\u062a \u0645\u06c1\u0645\u0627\u0646 \u0646\u0648\u0627\u0632\u06cc\u060c \u063a\u06cc\u0631\u062a\u060c \u0648\u0639\u062f\u06c1 \u062e\u0644\u0627\u0641\u06cc \u0633\u06d2 \u0646\u0641\u0631\u062a \u0627\u0648\u0631 \u062d\u062c\u0631\u06c1 \u06a9\u06cc \u0631\u0648\u0627\u06cc\u0627\u062a \u067e\u0631 \u0645\u0628\u0646\u06cc \u06c1\u06d2\u06d4 \u06c1\u0645\u06cc\u06ba \u0627\u067e\u0646\u06cc \u0645\u0627\u062f\u0631\u06cc \u0632\u0628\u0627\u0646 \u0633\u06cc\u06a9\u06be\u0646\u06cc \u0627\u0648\u0631 \u0628\u0648\u0644\u0646\u06cc \u0686\u0627\u06c1\u06cc\u06d2\u06d4 \u067e\u069a\u062a\u0648 \u06cc\u0648\u0647 \u0644\u0631\u063a\u0648\u0646\u06d0\u060c \u062e\u0648\u0696\u0647 \u0627\u0648 \u063a\u06cc\u0631\u062a\u064a \u0698\u0628\u0647 \u062f\u0647 \u0686\u06d0 \u0632\u0631\u06ab\u0648\u0646\u0647 \u06a9\u0644\u0648\u0646\u0647 \u062a\u0627\u0631\u06cc\u062e \u0644\u0631\u064a.\n\n\u067e\u069a\u062a\u0646\u064a \u06a9\u0644\u062a\u0648\u0631 \u067e\u0647 \u0645\u06d0\u0644\u0645\u0647 \u067e\u0627\u0644\u0646\u0647\u060c \u0646\u0646\u06ab\u060c \u0648\u0639\u062f\u0647 \u067e\u0648\u0631\u0647 \u06a9\u0648\u0644\u0648\u060c \u062f \u06a9\u0645\u0632\u0648\u0631\u0648 \u0644\u0627\u0633\u0646\u06cc\u0648\u064a\u060c \u0627\u0648 \u062f \u062d\u062c\u0631\u0648 \u067e\u0647 \u0645\u062c\u0644\u0633\u0648\u0646\u0648 \u0648\u0644\u0627\u0693 \u062f\u06cc.\n\n\u067e\u069a\u062a\u0648 \u067c\u067e\u06d0\u060c \u0686\u0627\u0631\u0628\u06d0\u062a\u06d0\u060c \u0644\u0646\u0689\u06cd \u0627\u0648 \u0627\u062a\u06bc \u0632\u0645\u0648\u0696 \u062f \u0645\u0644\u064a \u062e\u0648\u0646\u062f \u0627\u0648 \u0647\u0646\u0631 \u0685\u0631\u06ab\u0646\u062f\u0648\u0646\u0647 \u06a9\u0648\u064a.\n\n\u0645\u0648\u0696 \u0628\u0627\u06cc\u062f \u062e\u067e\u0644\u0647 \u0645\u0648\u0631\u0646\u06cd \u0698\u0628\u0647 \u067e\u069a\u062a\u0648 \u0648\u0644\u0648\u0644\u0648\u060c \u0648\u06cc\u06d0 \u0644\u06cc\u06a9\u0648\u060c \u0627\u0648 \u062f \u062e\u067e\u0644 \u06a9\u0644\u062a\u0648\u0631 \u0644\u0648\u0693 \u0627\u062e\u0644\u0627\u0642\u064a \u0627\u0635\u0648\u0644 \u067e\u0647 \u062e\u067e\u0644 \u0648\u0631\u0681\u0646\u064a \u0698\u0648\u0646\u062f \u06a9\u069a\u06d0 \u0639\u0645\u0644\u064a \u06a9\u0693\u0648.",
                "urdu": "\u0633\u0628\u0642 \"\u067e\u0634\u062a\u0648 \u062b\u0642\u0627\u0641\u062a\u060c \u0632\u0628\u0627\u0646 \u0627\u0648\u0631 \u0644\u0648\u06a9 \u0631\u0648\u0627\u06cc\u0627\u062a\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u067e\u0634\u062a\u0648 \u0627\u06cc\u06a9 \u0642\u062f\u06cc\u0645\u060c \u0634\u06cc\u0631\u06cc\u06ba \u0627\u0648\u0631 \u062a\u0627\u0631\u06cc\u062e\u06cc \u0632\u0628\u0627\u0646 \u06c1\u06d2\u06d4 \u067e\u062e\u062a\u0648\u0646 \u062b\u0642\u0627\u0641\u062a \u0645\u06c1\u0645\u0627\u0646 \u0646\u0648\u0627\u0632\u06cc\u060c \u063a\u06cc\u0631\u062a\u060c \u0648\u0639\u062f\u06c1 \u062e\u0644\u0627\u0641\u06cc \u0633\u06d2 \u0646\u0641\u0631\u062a \u0627\u0648\u0631 \u062d\u062c\u0631\u06c1 \u06a9\u06cc \u0631\u0648\u0627\u06cc\u0627\u062a \u067e\u0631 \u0645\u0628\u0646\u06cc \u06c1\u06d2\u06d4 \u06c1\u0645\u06cc\u06ba \u0627\u067e\u0646\u06cc \u0645\u0627\u062f\u0631\u06cc \u0632\u0628\u0627\u0646 \u0633\u06cc\u06a9\u06be\u0646\u06cc \u0627\u0648\u0631 \u0628\u0648\u0644\u0646\u06cc \u0686\u0627\u06c1\u06cc\u06d2\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u062f\u0631\u0633 \u0645\u0647\u0645 \u067c\u06a9\u064a \u0648\u0644\u06cc\u06a9\u0626.",
                "pashtoAns": "\u067e\u069a\u062a\u0648 \u06cc\u0648\u0647 \u0644\u0631\u063a\u0648\u0646\u06d0\u060c \u062e\u0648\u0696\u0647 \u0627\u0648 \u063a\u06cc\u0631\u062a\u064a \u0698\u0628\u0647 \u062f\u0647 \u0686\u06d0 \u0632\u0631\u06ab\u0648\u0646\u0647 \u06a9\u0644\u0648\u0646\u0647 \u062a\u0627\u0631\u06cc\u062e \u0644\u0631\u064a.\n\n\u067e\u069a\u062a\u0646\u064a \u06a9\u0644\u062a\u0648\u0631 \u067e\u0647 \u0645\u06d0\u0644\u0645\u0647 \u067e\u0627\u0644\u0646\u0647\u060c \u0646\u0646\u06ab\u060c \u0648\u0639\u062f\u0647 \u067e\u0648\u0631\u0647 \u06a9\u0648\u0644\u0648\u060c \u062f \u06a9\u0645\u0632\u0648\u0631\u0648 \u0644\u0627\u0633\u0646\u06cc\u0648\u064a\u060c \u0627\u0648 \u062f \u062d\u062c\u0631\u0648 \u067e\u0647 \u0645\u062c\u0644\u0633\u0648\u0646\u0648 \u0648\u0644\u0627\u0693 \u062f\u06cc.\n\n\u067e\u069a\u062a\u0648 \u067c\u067e\u06d0\u060c \u0686\u0627\u0631\u0628\u06d0\u062a\u06d0\u060c \u0644\u0646\u0689\u06cd \u0627\u0648 \u0627\u062a\u06bc \u0632\u0645\u0648\u0696 \u062f \u0645\u0644\u064a \u062e\u0648\u0646\u062f \u0627\u0648 \u0647\u0646\u0631 \u0685\u0631\u06ab\u0646\u062f\u0648\u0646\u0647 \u06a9\u0648\u064a.\n\n\u0645\u0648\u0696 \u0628\u0627\u06cc\u062f \u062e\u067e\u0644\u0647 \u0645\u0648\u0631\u0646\u06cd \u0698\u0628\u0647 \u067e\u069a\u062a\u0648 \u0648\u0644\u0648\u0644\u0648\u060c \u0648\u06cc\u06d0 \u0644\u06cc\u06a9\u0648\u060c \u0627\u0648 \u062f \u062e\u067e\u0644 \u06a9\u0644\u062a\u0648\u0631 \u0644\u0648\u0693 \u0627\u062e\u0644\u0627\u0642\u064a \u0627\u0635\u0648\u0644 \u067e\u0647 \u062e\u067e\u0644 \u0648\u0631\u0681\u0646\u064a \u0698\u0648\u0646\u062f \u06a9\u069a\u06d0 \u0639\u0645\u0644\u064a \u06a9\u0693\u0648."
        }
]
