                "ans": "\u067e\u0634\u062a\u0648 \u0627\u06cc\u06a9 \u0642\u062f\u06cc\u0645\u060c \u0634\u06cc\u0631\u06cc\u06ba \u0627\u0648\u0631 \u062a\u0627\u0631\u06cc\u062e\u06cc \u0632\u0628\u0627\u0646 \u06c1\u06d2\u06d4 \u067e\u062e\u062a\u0648\u0646 \u062b\u0642\u0627\u0641\u062a \u0645\u06c1\u0645\u0627\u0646 \u0646\u0648\u0627\u0632\u06cc\u060c \u063a\u06cc\u0631\u062a\u060c \u0648\u0639\u062f\u06c1 \u062e\u0644\u0627\u0641\u06cc \u0633\u06d2 \u0646\u0641\u0631\u062a \u0627\u0648\u0631 \u062d\u062c\u0631\u06c1 \u06a9\u06cc \u0631\u0648\u0627\u06cc\u0627\u062a \u067e\u0631 \u0645\u0628\u0646\u06cc \u06c1\u06d2\u06d4 \u06c1\u0645\u06cc\u06ba \u0627\u067e\u0646\u06cc \u0645\u0627\u062f\u0631\u06cc \u0632\u0628\u0627\u0646 \u0633\u06cc\u06a9\u06be\u0646\u06cc \u0627\u0648\u0631 \u0628\u0648\u0644\u0646\u06cc \u0686\u0627\u06c1\u06cc\u06d2\u06d4"
